CREATE FUNCTION photo.bump_v2_revision() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,photo AS $$
BEGIN
 IF OLD.revision >= 9223372036854775806 THEN
  RAISE EXCEPTION 'V2_REVISION_EXHAUSTED' USING ERRCODE='22003';
 END IF;
 NEW.revision := OLD.revision + 1;
 NEW.updated_at := statement_timestamp();
 RETURN NEW;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.bump_v2_revision() OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.bump_v2_revision() FROM PUBLIC;
CREATE TRIGGER v2_document_streams_revision BEFORE UPDATE ON photo.v2_document_streams
 FOR EACH ROW EXECUTE FUNCTION photo.bump_v2_revision();

-- Source: 00196_project_guards.sql
-- V21 admission guards; merge with 00196 only after all link classes are covered.
-- +goose StatementBegin
CREATE FUNCTION photo.guard_v2_workflow() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE r photo.runs%ROWTYPE; s photo.snapshots%ROWTYPE;
BEGIN
 SELECT * INTO r FROM photo.runs WHERE tenant_id=NEW.tenant_id AND id=NEW.run_id;
 SELECT * INTO s FROM photo.snapshots WHERE tenant_id=NEW.tenant_id AND id=NEW.input_snapshot_id;
 IF r.id IS NULL OR s.id IS NULL OR r.kind<>'v2' OR s.kind<>'v2'
  OR r.input_snapshot_id<>NEW.input_snapshot_id OR r.failure_policy<>'fail_fast'
  OR r.config_snapshot->>'project_id' IS DISTINCT FROM NEW.project_id::text THEN
  RAISE EXCEPTION 'V2_WORKFLOW_SCOPE_INVALID' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.guard_v2_workflow() OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.guard_v2_workflow() FROM PUBLIC;
CREATE TRIGGER v2_workflows_scope BEFORE INSERT ON photo.v2_workflows
 FOR EACH ROW EXECUTE FUNCTION photo.guard_v2_workflow();

-- +goose StatementBegin
CREATE FUNCTION photo.guard_v2_stream() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE source_project uuid;
BEGIN
 IF TG_OP='UPDATE' AND (NEW.tenant_id,NEW.project_id,NEW.asset_version_id,NEW.stream_type)
  IS DISTINCT FROM (OLD.tenant_id,OLD.project_id,OLD.asset_version_id,OLD.stream_type) THEN
  RAISE EXCEPTION 'V2_STREAM_SCOPE_IMMUTABLE' USING ERRCODE='23514';
 END IF;
 IF NEW.stream_type='draft' THEN
  SELECT a.project_id INTO source_project FROM photo.asset_versions v
   JOIN photo.assets a ON a.tenant_id=v.tenant_id AND a.id=v.asset_id
   WHERE v.tenant_id=NEW.tenant_id AND v.id=NEW.asset_version_id;
  IF source_project IS DISTINCT FROM NEW.project_id THEN
   RAISE EXCEPTION 'V2_STREAM_SOURCE_INVALID' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW.current_document_id IS NOT NULL AND NOT EXISTS(
  SELECT 1 FROM photo.v2_documents d WHERE d.tenant_id=NEW.tenant_id AND d.project_id=NEW.project_id
   AND d.stream_id=NEW.id AND d.id=NEW.current_document_id) THEN
  RAISE EXCEPTION 'V2_STREAM_CURRENT_INVALID' USING ERRCODE='23514';
 END IF;
 IF NEW.approved_document_id IS NOT NULL AND NOT EXISTS(
  SELECT 1 FROM photo.v2_documents d WHERE d.tenant_id=NEW.tenant_id AND d.project_id=NEW.project_id
   AND d.stream_id=NEW.id AND d.id=NEW.approved_document_id) THEN
  RAISE EXCEPTION 'V2_STREAM_APPROVED_INVALID' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.guard_v2_stream() OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.guard_v2_stream() FROM PUBLIC;
CREATE TRIGGER v2_document_streams_scope BEFORE INSERT OR UPDATE ON photo.v2_document_streams
 FOR EACH ROW EXECUTE FUNCTION photo.guard_v2_stream();

-- Source: 00196_artifact_guards.sql
-- Relational closure checks for V21; content validation stays in trusted services.
-- +goose StatementBegin
CREATE FUNCTION photo.guard_v2_artifact_link() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE artifact photo.artifacts%ROWTYPE; parent_ok boolean;
BEGIN
 SELECT * INTO artifact FROM photo.artifacts a WHERE a.tenant_id=NEW.tenant_id AND a.id=NEW.artifact_id;
 IF artifact.id IS NULL OR artifact.sha256<>NEW.sha256 OR artifact.state<>'ready'
  OR artifact.object_version IS NULL OR artifact.verified_at IS NULL
  OR (artifact.expires_at IS NOT NULL AND artifact.expires_at<=clock_timestamp()) THEN
  RAISE EXCEPTION 'V2_ARTIFACT_UNVERIFIED' USING ERRCODE='23514';
 END IF;
 CASE TG_TABLE_NAME
  WHEN 'v2_documents' THEN
   SELECT EXISTS(SELECT 1 FROM photo.v2_document_streams s
    WHERE s.tenant_id=NEW.tenant_id AND s.project_id=NEW.project_id AND s.id=NEW.stream_id)
    INTO parent_ok;
  WHEN 'v2_document_refs' THEN
   SELECT EXISTS(SELECT 1 FROM photo.v2_documents d
    WHERE d.tenant_id=NEW.tenant_id AND d.project_id=NEW.project_id AND d.id=NEW.document_id)
    INTO parent_ok;
  WHEN 'v2_artifact_links' THEN
   SELECT EXISTS(SELECT 1 FROM photo.v2_workflows w
    WHERE w.tenant_id=NEW.tenant_id AND w.project_id=NEW.project_id AND w.id=NEW.workflow_id)
    INTO parent_ok;
  WHEN 'v2_task_inputs' THEN
   SELECT EXISTS(SELECT 1 FROM photo.tasks t
    JOIN photo.v2_workflows w ON w.tenant_id=t.tenant_id AND w.run_id=t.run_id
    WHERE t.tenant_id=NEW.tenant_id AND t.id=NEW.task_id AND w.project_id=NEW.project_id)
    INTO parent_ok;
  ELSE
   RAISE EXCEPTION 'V2_ARTIFACT_LINK_TABLE_INVALID' USING ERRCODE='23514';
 END CASE;
 IF NOT parent_ok THEN
  RAISE EXCEPTION 'V2_ARTIFACT_LINK_SCOPE_INVALID' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.guard_v2_artifact_link() OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.guard_v2_artifact_link() FROM PUBLIC;
CREATE TRIGGER v2_documents_artifact_guard BEFORE INSERT ON photo.v2_documents
 FOR EACH ROW EXECUTE FUNCTION photo.guard_v2_artifact_link();
CREATE TRIGGER v2_document_refs_artifact_guard BEFORE INSERT ON photo.v2_document_refs
 FOR EACH ROW EXECUTE FUNCTION photo.guard_v2_artifact_link();
CREATE TRIGGER v2_artifact_links_artifact_guard BEFORE INSERT ON photo.v2_artifact_links
 FOR EACH ROW EXECUTE FUNCTION photo.guard_v2_artifact_link();
CREATE TRIGGER v2_task_inputs_artifact_guard BEFORE INSERT ON photo.v2_task_inputs
 FOR EACH ROW EXECUTE FUNCTION photo.guard_v2_artifact_link();

-- Source: 00196_review_guards.sql
-- Approval/review rows are immutable evidence; validate relational authority at insert.
-- +goose StatementBegin
CREATE FUNCTION photo.guard_v2_approval() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
BEGIN
 IF NOT EXISTS(
  SELECT 1 FROM photo.v2_documents d
  JOIN photo.v2_document_streams s ON s.tenant_id=d.tenant_id AND s.id=d.stream_id
  WHERE d.tenant_id=NEW.tenant_id AND d.project_id=NEW.project_id AND d.id=NEW.document_id
   AND d.document_type='EditingRecipeV3' AND d.sha256=NEW.recipe_sha
   AND s.stream_type='draft' AND s.current_document_id=d.id
 ) OR NOT EXISTS(
  SELECT 1 FROM photo.artifacts a WHERE a.tenant_id=NEW.tenant_id AND a.id=NEW.resolved_artifact_id
   AND a.state='ready' AND a.object_version IS NOT NULL AND a.verified_at IS NOT NULL
 ) OR NOT EXISTS(
  SELECT 1 FROM photo.memberships m WHERE m.tenant_id=NEW.tenant_id AND m.user_id=NEW.actor_id
   AND m.status='active' AND m.role IN('owner','admin','editor')
 ) THEN
  RAISE EXCEPTION 'V2_APPROVAL_INVALID' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.guard_v2_approval() OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.guard_v2_approval() FROM PUBLIC;
CREATE TRIGGER v2_document_approvals_guard BEFORE INSERT ON photo.v2_document_approvals
 FOR EACH ROW EXECUTE FUNCTION photo.guard_v2_approval();

-- +goose StatementBegin
CREATE FUNCTION photo.guard_v2_review_batch() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
BEGIN
 IF NOT EXISTS(
  SELECT 1 FROM photo.v2_workflows w WHERE w.tenant_id=NEW.tenant_id
   AND w.project_id=NEW.project_id AND w.id=NEW.workflow_id
 ) OR NOT EXISTS(
  SELECT 1 FROM photo.artifacts a WHERE a.tenant_id=NEW.tenant_id AND a.id=NEW.decisions_artifact_id
   AND a.state='ready' AND a.object_version IS NOT NULL AND a.verified_at IS NOT NULL
 ) OR NOT EXISTS(
  SELECT 1 FROM photo.memberships m WHERE m.tenant_id=NEW.tenant_id AND m.user_id=NEW.actor_id
   AND m.status='active' AND m.role IN('owner','admin','editor')
 ) OR (NEW.child_run_id IS NOT NULL AND NOT EXISTS(
  SELECT 1 FROM photo.runs r WHERE r.tenant_id=NEW.tenant_id AND r.id=NEW.child_run_id
   AND r.kind IN('apply','v2') AND r.config_snapshot->>'project_id'=NEW.project_id::text
 )) THEN
  RAISE EXCEPTION 'V2_REVIEW_BATCH_INVALID' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.guard_v2_review_batch() OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.guard_v2_review_batch() FROM PUBLIC;
CREATE TRIGGER v2_review_batches_guard BEFORE INSERT ON photo.v2_review_batches
 FOR EACH ROW EXECUTE FUNCTION photo.guard_v2_review_batch();

-- Source: 00196_authority.sql
-- Revalidate authenticated session and project edit rights inside every v2 mutation.
-- +goose StatementBegin
CREATE FUNCTION photo.v2_editor_authorized(p_tenant uuid,p_project uuid,p_actor uuid,p_session uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
 SELECT EXISTS(
  SELECT 1 FROM photo.authorize_tenant(p_actor,p_session,p_tenant) auth
  JOIN photo.projects p ON p.tenant_id=p_tenant AND p.id=p_project AND p.archived_at IS NULL
  WHERE auth.role IN('owner','admin') OR
   (auth.role='editor' AND (p.visibility='workspace' OR EXISTS(
    SELECT 1 FROM photo.project_acl acl WHERE acl.tenant_id=p_tenant AND acl.project_id=p_project
     AND acl.user_id=p_actor AND acl.role='editor')))
 )
$$;
-- +goose StatementEnd
ALTER FUNCTION photo.v2_editor_authorized(uuid,uuid,uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.v2_editor_authorized(uuid,uuid,uuid,uuid) FROM PUBLIC;

