-- The existing tenant RLS policy limits these read-only rows to app.tenant_id.
GRANT SELECT ON photo.task_results TO photo_api;

-- Source: 00196_draft_publication.sql
-- Fenced publication for user-authored immutable V2 JSON documents.
CREATE TABLE photo.v2_draft_uploads(
 tenant_id uuid NOT NULL REFERENCES photo.tenants(id),
 document_id uuid NOT NULL,
 project_id uuid NOT NULL,
 asset_version_id uuid NOT NULL,
 artifact_id uuid NOT NULL,
 sha256 text NOT NULL CHECK(sha256~'^[0-9a-f]{64}$'),
 bytes bigint NOT NULL CHECK(bytes BETWEEN 2 AND 1048576),
 bucket text NOT NULL CHECK(length(bucket) BETWEEN 3 AND 63),
 state text NOT NULL DEFAULT 'pending' CHECK(state IN('pending','cleaning','abandoned','ready','retired')),
 token uuid NOT NULL DEFAULT gen_random_uuid(),
 object_version text,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 completed_at timestamptz,
 cleanup_after timestamptz NOT NULL DEFAULT clock_timestamp()+interval '3 hours',
 cleanup_lease_until timestamptz,
 PRIMARY KEY(tenant_id,document_id),UNIQUE(tenant_id,artifact_id),
 FOREIGN KEY(tenant_id,project_id) REFERENCES photo.projects(tenant_id,id),
 FOREIGN KEY(tenant_id,asset_version_id) REFERENCES photo.asset_versions(tenant_id,id),
 CHECK((state IN('ready','retired'))=(object_version IS NOT NULL AND completed_at IS NOT NULL)),
 CHECK((state='cleaning')=(cleanup_lease_until IS NOT NULL))
);
ALTER TABLE photo.v2_draft_uploads ENABLE ROW LEVEL SECURITY;
ALTER TABLE photo.v2_draft_uploads FORCE ROW LEVEL SECURITY;
CREATE POLICY trusted_functions ON photo.v2_draft_uploads TO photo_fn_owner USING(true) WITH CHECK(true);
GRANT SELECT,INSERT,UPDATE,DELETE ON photo.v2_draft_uploads TO photo_fn_owner;

-- +goose StatementBegin
CREATE FUNCTION photo.reserve_v2_draft_upload(p_tenant uuid,p_version uuid,p_document uuid,
 p_actor uuid,p_session uuid,p_sha text,p_bytes bigint,p_bucket text)
RETURNS TABLE(outcome text,artifact_id uuid,token uuid,ready boolean)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE d photo.v2_draft_uploads%ROWTYPE; project uuid; asset uuid; latest_version uuid;
 capacity numeric; used numeric;
 aid uuid:=gen_random_uuid(); fence uuid:=gen_random_uuid();
BEGIN
 IF p_tenant IS NULL OR p_version IS NULL OR p_document IS NULL OR p_actor IS NULL OR p_session IS NULL
  OR p_sha IS NULL OR p_sha !~ '^[0-9a-f]{64}$' OR p_bytes IS NULL OR p_bytes NOT BETWEEN 2 AND 1048576
  OR p_bucket IS NULL OR length(p_bucket) NOT BETWEEN 3 AND 63
  OR p_tenant IS DISTINCT FROM nullif(current_setting('app.tenant_id',true),'')::uuid THEN
  RAISE EXCEPTION 'INVALID_V2_DRAFT_UPLOAD' USING ERRCODE='22023';
 END IF;
 PERFORM id FROM photo.tenant_usage WHERE tenant_id=p_tenant FOR UPDATE;
 SELECT a.project_id,a.id INTO project,asset FROM photo.asset_versions v
 JOIN photo.assets a ON a.tenant_id=v.tenant_id AND a.id=v.asset_id
 JOIN photo.tenants t ON t.id=v.tenant_id AND t.status='active'
 WHERE v.tenant_id=p_tenant AND v.id=p_version AND v.review_state='accepted'
  AND a.deleted_at IS NULL AND a.upload_state='verified'
  FOR UPDATE OF a FOR SHARE OF v;
 IF project IS NULL OR NOT photo.v2_editor_authorized(p_tenant,project,p_actor,p_session) THEN
  RETURN QUERY SELECT 'forbidden',NULL::uuid,NULL::uuid,false;RETURN;
 END IF;
 SELECT id INTO latest_version FROM photo.asset_versions
  WHERE tenant_id=p_tenant AND asset_id=asset ORDER BY version_no DESC LIMIT 1;
 IF latest_version IS DISTINCT FROM p_version THEN
  RETURN QUERY SELECT 'conflict',NULL::uuid,NULL::uuid,false;RETURN;
 END IF;
 SELECT * INTO d FROM photo.v2_draft_uploads x WHERE x.tenant_id=p_tenant AND x.document_id=p_document FOR UPDATE;
 IF FOUND THEN
  IF d.project_id<>project OR d.asset_version_id<>p_version OR d.sha256<>p_sha
   OR d.bytes<>p_bytes OR d.bucket<>p_bucket THEN
   RETURN QUERY SELECT 'conflict',NULL::uuid,NULL::uuid,false;RETURN;
  END IF;
  IF d.state='ready' THEN
   IF NOT EXISTS(SELECT 1 FROM photo.artifacts a WHERE a.tenant_id=p_tenant AND a.id=d.artifact_id
    AND a.sha256=d.sha256 AND a.object_version=d.object_version AND a.state='ready') THEN
    RETURN QUERY SELECT 'stale',NULL::uuid,NULL::uuid,false;RETURN;
   END IF;
   RETURN QUERY SELECT 'replayed',d.artifact_id,d.token,true;RETURN;
  END IF;
  IF d.state<>'pending' THEN RETURN QUERY SELECT 'stale',NULL::uuid,NULL::uuid,false;RETURN;END IF;
  UPDATE photo.v2_draft_uploads SET token=fence WHERE tenant_id=p_tenant AND document_id=p_document;
  RETURN QUERY SELECT 'resumed',d.artifact_id,fence,false;RETURN;
 END IF;
 SELECT (quotas->>'storage_bytes')::numeric INTO capacity FROM photo.tenants WHERE id=p_tenant;
 SELECT storage_bytes::numeric+reserved_bytes INTO used FROM photo.tenant_usage WHERE tenant_id=p_tenant;
 IF capacity IS NULL OR used IS NULL OR used+p_bytes>capacity OR used+p_bytes>9007199254740991 THEN
  RETURN QUERY SELECT 'quota',NULL::uuid,NULL::uuid,false;RETURN;
 END IF;
 INSERT INTO photo.v2_draft_uploads(tenant_id,document_id,project_id,asset_version_id,artifact_id,sha256,bytes,bucket,token)
 VALUES(p_tenant,p_document,project,p_version,aid,p_sha,p_bytes,p_bucket,fence);
 UPDATE photo.tenant_usage SET reserved_bytes=reserved_bytes+p_bytes WHERE tenant_id=p_tenant;
 RETURN QUERY SELECT 'created',aid,fence,false;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.reserve_v2_draft_upload(uuid,uuid,uuid,uuid,uuid,text,bigint,text) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.reserve_v2_draft_upload(uuid,uuid,uuid,uuid,uuid,text,bigint,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.reserve_v2_draft_upload(uuid,uuid,uuid,uuid,uuid,text,bigint,text) TO photo_api;

-- +goose StatementBegin
CREATE FUNCTION photo.complete_v2_draft_upload(p_tenant uuid,p_version uuid,p_document uuid,
 p_actor uuid,p_session uuid,p_artifact uuid,p_token uuid,p_sha text,p_bytes bigint,
 p_bucket text,p_object_version text) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE d photo.v2_draft_uploads%ROWTYPE; target text;
BEGIN
 IF p_tenant IS DISTINCT FROM nullif(current_setting('app.tenant_id',true),'')::uuid
  OR p_object_version IS NULL OR p_object_version IN('','null') OR length(p_object_version)>1024 THEN RETURN false;END IF;
 PERFORM id FROM photo.tenant_usage WHERE tenant_id=p_tenant FOR UPDATE;
 SELECT * INTO d FROM photo.v2_draft_uploads x WHERE x.tenant_id=p_tenant AND x.document_id=p_document FOR UPDATE;
 IF NOT FOUND OR d.asset_version_id<>p_version OR d.artifact_id<>p_artifact OR d.token<>p_token
  OR d.sha256<>p_sha OR d.bytes<>p_bytes OR d.bucket<>p_bucket
  OR NOT photo.v2_editor_authorized(p_tenant,d.project_id,p_actor,p_session) THEN RETURN false;END IF;
 IF d.state='ready' THEN RETURN d.object_version=p_object_version;END IF;
 IF d.state<>'pending' THEN RETURN false;END IF;
 target:='tenants/'||p_tenant||'/v2-drafts/'||p_artifact;
 INSERT INTO photo.artifacts(id,tenant_id,bucket,object_key,object_version,sha256,bytes,media_type,state,verified_at,output_role)
 VALUES(p_artifact,p_tenant,p_bucket,target,p_object_version,p_sha,p_bytes,'application/json','ready',clock_timestamp(),'document');
 UPDATE photo.tenant_usage SET reserved_bytes=reserved_bytes-p_bytes,storage_bytes=storage_bytes+p_bytes
  WHERE tenant_id=p_tenant AND reserved_bytes>=p_bytes;
 IF NOT FOUND THEN RAISE EXCEPTION 'DRAFT_QUOTA_ACCOUNTING' USING ERRCODE='23514';END IF;
 UPDATE photo.v2_draft_uploads SET state='ready',object_version=p_object_version,completed_at=clock_timestamp()
  WHERE tenant_id=p_tenant AND document_id=p_document;
 RETURN true;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.complete_v2_draft_upload(uuid,uuid,uuid,uuid,uuid,uuid,uuid,text,bigint,text,text) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.complete_v2_draft_upload(uuid,uuid,uuid,uuid,uuid,uuid,uuid,text,bigint,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.complete_v2_draft_upload(uuid,uuid,uuid,uuid,uuid,uuid,uuid,text,bigint,text,text) TO photo_api;

-- Expired pending objects may exist after an uncertain PUT. A claim fences
-- both API completion and reservation replay before storage is touched.
-- +goose StatementBegin
CREATE FUNCTION photo.claim_v2_draft_upload_cleanup()
RETURNS TABLE(tenant_id uuid,document_id uuid,artifact_id uuid,bucket text,cleanup_token uuid)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE hint photo.v2_draft_uploads%ROWTYPE; d photo.v2_draft_uploads%ROWTYPE;
 fence uuid:=gen_random_uuid();
BEGIN
 SELECT * INTO hint FROM photo.v2_draft_uploads x
 WHERE (x.state='pending' AND x.cleanup_after<=clock_timestamp())
  OR (x.state='cleaning' AND x.cleanup_lease_until<=clock_timestamp())
 ORDER BY x.cleanup_after,x.artifact_id LIMIT 1;
 IF NOT FOUND THEN RETURN;END IF;
 PERFORM id FROM photo.tenant_usage WHERE tenant_usage.tenant_id=hint.tenant_id FOR UPDATE;
 SELECT * INTO d FROM photo.v2_draft_uploads x
  WHERE x.tenant_id=hint.tenant_id AND x.document_id=hint.document_id FOR UPDATE;
 IF NOT FOUND OR NOT ((d.state='pending' AND d.cleanup_after<=clock_timestamp())
  OR (d.state='cleaning' AND d.cleanup_lease_until<=clock_timestamp()))
  OR EXISTS(SELECT FROM photo.artifacts a WHERE a.tenant_id=d.tenant_id AND a.id=d.artifact_id) THEN RETURN;END IF;
 UPDATE photo.v2_draft_uploads x SET state='cleaning',token=fence,
  cleanup_lease_until=clock_timestamp()+interval '90 seconds'
  WHERE x.tenant_id=d.tenant_id AND x.document_id=d.document_id;
 RETURN QUERY SELECT d.tenant_id,d.document_id,d.artifact_id,d.bucket,fence;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.claim_v2_draft_upload_cleanup() OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.claim_v2_draft_upload_cleanup() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.claim_v2_draft_upload_cleanup() TO photo_maintenance;

-- +goose StatementBegin
CREATE FUNCTION photo.finish_v2_draft_upload_cleanup(p_tenant uuid,p_document uuid,p_token uuid)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE d photo.v2_draft_uploads%ROWTYPE;
BEGIN
 IF p_tenant IS NULL OR p_document IS NULL OR p_token IS NULL THEN RETURN false;END IF;
 PERFORM id FROM photo.tenant_usage WHERE tenant_id=p_tenant FOR UPDATE;
 SELECT * INTO d FROM photo.v2_draft_uploads x
  WHERE x.tenant_id=p_tenant AND x.document_id=p_document FOR UPDATE;
 IF NOT FOUND OR d.state<>'cleaning' OR d.token<>p_token
  OR d.cleanup_lease_until<=clock_timestamp() OR
  EXISTS(SELECT FROM photo.artifacts a WHERE a.tenant_id=p_tenant AND a.id=d.artifact_id) THEN RETURN false;END IF;
 UPDATE photo.tenant_usage SET reserved_bytes=reserved_bytes-d.bytes
  WHERE tenant_id=p_tenant AND reserved_bytes>=d.bytes;
 IF NOT FOUND THEN RAISE EXCEPTION 'DRAFT_CLEANUP_ACCOUNTING' USING ERRCODE='23514';END IF;
 UPDATE photo.v2_draft_uploads SET state='abandoned',cleanup_lease_until=NULL
  WHERE tenant_id=p_tenant AND document_id=p_document;
 RETURN true;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.finish_v2_draft_upload_cleanup(uuid,uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.finish_v2_draft_upload_cleanup(uuid,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.finish_v2_draft_upload_cleanup(uuid,uuid,uuid) TO photo_maintenance;

-- Ready uploads remain pinned while clients retry a save. After 24 hours the
-- immutable document tables, if any, own the artifact; existing GC handles an
-- unreferenced artifact after this upload reservation is retired.
-- +goose StatementBegin
CREATE FUNCTION photo.retire_one_v2_draft_upload() RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE d photo.v2_draft_uploads%ROWTYPE;
BEGIN
 SELECT * INTO d FROM photo.v2_draft_uploads x WHERE x.state='ready'
  AND x.completed_at<clock_timestamp()-interval '24 hours'
 ORDER BY x.completed_at,x.artifact_id LIMIT 1 FOR UPDATE SKIP LOCKED;
 IF NOT FOUND THEN RETURN false;END IF;
 UPDATE photo.v2_draft_uploads SET state='retired' WHERE tenant_id=d.tenant_id AND document_id=d.document_id;
 RETURN true;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.retire_one_v2_draft_upload() OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.retire_one_v2_draft_upload() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.retire_one_v2_draft_upload() TO photo_maintenance;

-- Source: 00196_draft_scope.sql
-- Resolve V21 document dependencies only through project-bound provenance.
-- Tenant equality alone cannot authorize a user-supplied ArtifactRef.
-- +goose StatementBegin
CREATE FUNCTION photo.v2_draft_artifact_scope(p_tenant uuid,p_project uuid,p_version uuid,
 p_artifact uuid,p_sha text,p_contract text,p_actor uuid,p_session uuid,
 p_parent uuid,p_parent_sha text)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE item photo.artifacts%ROWTYPE;
BEGIN
 IF p_tenant IS NULL OR p_project IS NULL OR p_version IS NULL OR p_artifact IS NULL
  OR p_actor IS NULL OR p_session IS NULL OR coalesce(p_sha,'') !~ '^[0-9a-f]{64}$'
  OR p_tenant IS DISTINCT FROM nullif(current_setting('app.tenant_id',true),'')::uuid
  OR NOT photo.v2_editor_authorized(p_tenant,p_project,p_actor,p_session) THEN RETURN false;END IF;
 SELECT * INTO item FROM photo.artifacts a WHERE a.tenant_id=p_tenant AND a.id=p_artifact
  AND a.sha256=p_sha AND a.state='ready' AND a.verified_at IS NOT NULL
  AND a.object_version IS NOT NULL AND a.object_version NOT IN('','null')
  AND (a.expires_at IS NULL OR a.expires_at>clock_timestamp());
 IF NOT FOUND THEN RETURN false;END IF;
 IF p_contract='WorkingImage' THEN
  RETURN item.output_role='working_image' AND item.media_type='application/json' AND EXISTS(
   SELECT 1 FROM photo.asset_versions v JOIN photo.assets a
    ON a.tenant_id=v.tenant_id AND a.id=v.asset_id
   WHERE v.tenant_id=p_tenant AND a.project_id=p_project
    AND a.deleted_at IS NULL AND v.review_state='accepted'
    AND v.master_artifact_id=p_artifact AND v.content_hash=p_sha);
 ELSIF p_contract IN('WorkingPixels','WorkingAlpha') THEN
  RETURN item.output_role=CASE p_contract WHEN 'WorkingPixels' THEN 'working_rgb' ELSE 'alpha' END
   AND p_parent IS NOT NULL AND coalesce(p_parent_sha,'') ~ '^[0-9a-f]{64}$'
   AND EXISTS(SELECT 1 FROM photo.asset_versions v JOIN photo.assets a
    ON a.tenant_id=v.tenant_id AND a.id=v.asset_id
    JOIN photo.artifacts source ON source.tenant_id=v.tenant_id
     AND source.id=v.master_artifact_id AND source.sha256=v.content_hash
    WHERE v.tenant_id=p_tenant AND a.project_id=p_project
     AND v.review_state='accepted' AND source.id=p_parent AND source.sha256=p_parent_sha
     AND source.output_role='working_image'
     AND source.created_by_task_id=item.created_by_task_id
     AND source.produced_attempt=item.produced_attempt
     AND source.produced_fence=item.produced_fence
     AND item.created_by_task_id IS NOT NULL AND item.produced_attempt IS NOT NULL
     AND item.produced_fence IS NOT NULL);
 ELSIF p_contract='StyleV2' THEN
  RETURN item.media_type='application/json' AND EXISTS(
   SELECT 1 FROM photo.style_versions v JOIN photo.styles s
    ON s.tenant_id=v.tenant_id AND s.id=v.style_id
   WHERE v.tenant_id=p_tenant AND s.project_id=p_project AND s.archived_at IS NULL
    AND v.export_artifact_id=p_artifact AND v.config_hash=p_sha
    AND v.approval_status='accepted' AND v.schema_version='2.0.0'
    AND v.renderer_version='photo_renderer_v2');
 ELSIF p_contract NOT IN('LayerStack','MaskRef','Params','CorrectionPlan',
   'Override','MaskPixels','DenseWarpField','Artifact') THEN RETURN false;
 END IF;
 RETURN EXISTS(SELECT 1 FROM photo.v2_draft_uploads u
   WHERE u.tenant_id=p_tenant AND u.project_id=p_project AND u.asset_version_id=p_version
    AND u.artifact_id=p_artifact AND u.sha256=p_sha AND u.state='ready')
  OR EXISTS(SELECT 1 FROM photo.v2_documents d JOIN photo.v2_document_streams s
   ON s.tenant_id=d.tenant_id AND s.id=d.stream_id
   WHERE d.tenant_id=p_tenant AND d.project_id=p_project AND s.asset_version_id=p_version
    AND d.artifact_id=p_artifact AND d.sha256=p_sha)
  OR EXISTS(SELECT 1 FROM photo.tasks task JOIN photo.runs r
   ON r.tenant_id=task.tenant_id AND r.id=task.run_id
   LEFT JOIN photo.v2_workflows w ON w.tenant_id=r.tenant_id AND w.run_id=r.id
   WHERE task.tenant_id=p_tenant AND task.id=item.created_by_task_id
    AND (w.project_id=p_project OR r.config_snapshot->>'project_id'=p_project::text))
  OR EXISTS(SELECT 1 FROM photo.style_asset_bindings b
   JOIN photo.style_versions v ON v.tenant_id=b.tenant_id AND v.id=b.style_version_id
   JOIN photo.styles s ON s.tenant_id=v.tenant_id AND s.id=v.style_id
   WHERE b.tenant_id=p_tenant AND s.project_id=p_project
    AND b.artifact_id=p_artifact AND b.sha256=p_sha);
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.v2_draft_artifact_scope(uuid,uuid,uuid,uuid,text,text,uuid,uuid,uuid,text) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.v2_draft_artifact_scope(uuid,uuid,uuid,uuid,text,text,uuid,uuid,uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.v2_draft_artifact_scope(uuid,uuid,uuid,uuid,text,text,uuid,uuid,uuid,text) TO photo_api;

-- Compatibility for scope probes that do not inspect nested pixel lineage.
-- +goose StatementBegin
CREATE FUNCTION photo.v2_draft_artifact_scope(p_tenant uuid,p_project uuid,p_version uuid,
 p_artifact uuid,p_sha text,p_contract text,p_actor uuid,p_session uuid)
RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
 SELECT photo.v2_draft_artifact_scope(p_tenant,p_project,p_version,p_artifact,
  p_sha,p_contract,p_actor,p_session,NULL::uuid,NULL::text)
$$;
-- +goose StatementEnd
ALTER FUNCTION photo.v2_draft_artifact_scope(uuid,uuid,uuid,uuid,text,text,uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.v2_draft_artifact_scope(uuid,uuid,uuid,uuid,text,text,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.v2_draft_artifact_scope(uuid,uuid,uuid,uuid,text,text,uuid,uuid) TO photo_api;

-- Source: 00196_draft_refs.sql
-- Insert the validated nested artifact closure in the same transaction as a document.
-- +goose StatementBegin
CREATE FUNCTION photo.register_v2_document_refs(p_tenant uuid,p_project uuid,p_document uuid,p_refs jsonb)
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE ref record; n integer:=0;
BEGIN
 IF p_refs IS NULL OR jsonb_typeof(p_refs)<>'array' THEN
  RAISE EXCEPTION 'V2_CLOSURE_INVALID' USING ERRCODE='22023';
 END IF;
 IF jsonb_array_length(p_refs)>512 OR pg_column_size(p_refs)>1048576 THEN
  RAISE EXCEPTION 'V2_CLOSURE_INVALID' USING ERRCODE='22023';
 END IF;
 FOR ref IN SELECT value,ordinality-1 AS ordinal FROM jsonb_array_elements(p_refs) WITH ORDINALITY LOOP
  IF jsonb_typeof(ref.value)<>'object' THEN
   RAISE EXCEPTION 'V2_CLOSURE_INVALID' USING ERRCODE='22023';
  END IF;
  IF (SELECT count(*) FROM jsonb_object_keys(ref.value))<>4 OR
   NOT (ref.value ?& ARRAY['artifact_id','sha256','purpose','ordinal']) OR
   coalesce(ref.value->>'artifact_id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' OR
   coalesce(ref.value->>'sha256','') !~ '^[0-9a-f]{64}$' OR
   coalesce(ref.value->>'purpose','') !~ '^[0-9a-f]{64}$' OR
   coalesce(ref.value->>'ordinal','') !~ '^[0-9]{1,3}$' THEN
   RAISE EXCEPTION 'V2_CLOSURE_INVALID' USING ERRCODE='22023';
  END IF;
  IF (ref.value->>'ordinal')::integer<>ref.ordinal THEN
   RAISE EXCEPTION 'V2_CLOSURE_INVALID' USING ERRCODE='22023';
  END IF;
  INSERT INTO photo.v2_document_refs(tenant_id,project_id,document_id,artifact_id,sha256,purpose,ordinal)
  VALUES(p_tenant,p_project,p_document,(ref.value->>'artifact_id')::uuid,
   ref.value->>'sha256',ref.value->>'purpose',ref.ordinal);
  n:=n+1;
 END LOOP;
 RETURN n;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.register_v2_document_refs(uuid,uuid,uuid,jsonb) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.register_v2_document_refs(uuid,uuid,uuid,jsonb) FROM PUBLIC;

-- Source: 00196_draft_mutations.sql
-- Server stages/validates recipe bytes and closure before this DB-only transaction.
-- First save includes a server-generated base checkpoint; later saves omit it.
-- +goose StatementBegin
CREATE FUNCTION photo.replace_v2_draft(
 p_tenant uuid,p_asset_version uuid,p_expected bigint,p_document uuid,p_artifact uuid,p_sha text,
 p_actor uuid,p_session uuid,p_refs jsonb,p_base_document uuid,p_base_artifact uuid,
 p_base_sha text,p_base_refs jsonb,p_layer_document uuid,p_layer_artifact uuid,
 p_layer_sha text,p_layer_refs jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE project uuid; asset uuid; latest_version uuid;
 stream photo.v2_document_streams%ROWTYPE; next_version bigint;
BEGIN
 IF p_tenant IS NULL OR p_asset_version IS NULL OR p_document IS NULL OR p_artifact IS NULL
  OR p_actor IS NULL OR p_session IS NULL OR p_expected IS NULL OR p_expected<0
  OR coalesce(p_sha,'') !~ '^[0-9a-f]{64}$' THEN
  RAISE EXCEPTION 'V2_DRAFT_INVALID' USING ERRCODE='22023';
 END IF;
 PERFORM id FROM photo.tenants WHERE id=p_tenant AND status='active' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'V2_TENANT_UNAVAILABLE' USING ERRCODE='42501';END IF;
 SELECT a.project_id,a.id INTO project,asset FROM photo.asset_versions v
 JOIN photo.assets a ON a.tenant_id=v.tenant_id AND a.id=v.asset_id
 WHERE v.tenant_id=p_tenant AND v.id=p_asset_version AND v.review_state='accepted'
  AND a.deleted_at IS NULL AND a.upload_state='verified'
  FOR UPDATE OF a FOR SHARE OF v;
 IF project IS NULL OR NOT photo.v2_editor_authorized(p_tenant,project,p_actor,p_session) THEN
  RAISE EXCEPTION 'V2_DRAFT_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 SELECT id INTO latest_version FROM photo.asset_versions
  WHERE tenant_id=p_tenant AND asset_id=asset ORDER BY version_no DESC LIMIT 1;
 IF latest_version IS DISTINCT FROM p_asset_version THEN
  RAISE EXCEPTION 'V2_DRAFT_SOURCE_STALE' USING ERRCODE='40001';
 END IF;
 SELECT * INTO stream FROM photo.v2_document_streams
  WHERE tenant_id=p_tenant AND asset_version_id=p_asset_version AND stream_type='draft' FOR UPDATE;
 IF NOT FOUND THEN
  IF p_expected<>0 OR p_base_document IS NULL OR p_base_artifact IS NULL
   OR coalesce(p_base_sha,'') !~ '^[0-9a-f]{64}$' OR p_base_refs IS NULL
   OR p_base_document=p_document THEN
   RAISE EXCEPTION 'V2_DRAFT_REVISION_CONFLICT' USING ERRCODE='40001';
  END IF;
  INSERT INTO photo.v2_document_streams(tenant_id,project_id,asset_version_id,stream_type)
   VALUES(p_tenant,project,p_asset_version,'draft') ON CONFLICT DO NOTHING;
  SELECT * INTO stream FROM photo.v2_document_streams
   WHERE tenant_id=p_tenant AND asset_version_id=p_asset_version AND stream_type='draft' FOR UPDATE;
  IF NOT FOUND OR stream.revision<>1 OR stream.current_document_id IS NOT NULL THEN
   RAISE EXCEPTION 'V2_DRAFT_REVISION_CONFLICT' USING ERRCODE='40001';
  END IF;
  PERFORM 1 FROM photo.v2_draft_uploads u WHERE u.tenant_id=p_tenant
   AND u.project_id=project AND u.asset_version_id=p_asset_version
   AND u.document_id=p_base_document AND u.artifact_id=p_base_artifact
   AND u.sha256=p_base_sha AND u.state='ready' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'V2_DRAFT_BASE_NOT_READY' USING ERRCODE='23514';END IF;
  INSERT INTO photo.v2_documents(id,tenant_id,project_id,stream_id,version_no,document_type,artifact_id,sha256)
   VALUES(p_base_document,p_tenant,project,stream.id,1,'EditingRecipeV3',p_base_artifact,p_base_sha);
  PERFORM photo.register_v2_document_refs(p_tenant,project,p_base_document,p_base_refs);
  next_version:=2;
 ELSE
  IF stream.project_id<>project OR stream.revision<>p_expected OR p_expected<1
   OR p_base_document IS NOT NULL OR p_base_artifact IS NOT NULL OR p_base_sha IS NOT NULL
   OR p_base_refs IS DISTINCT FROM '[]'::jsonb THEN
   RAISE EXCEPTION 'V2_DRAFT_REVISION_CONFLICT' USING ERRCODE='40001';
  END IF;
  SELECT max(version_no)+1 INTO next_version FROM photo.v2_documents
   WHERE tenant_id=p_tenant AND stream_id=stream.id;
  IF next_version IS NULL THEN
   RAISE EXCEPTION 'V2_DRAFT_HISTORY_INVALID' USING ERRCODE='23514';
  END IF;
 END IF;
 PERFORM 1 FROM photo.v2_draft_uploads u WHERE u.tenant_id=p_tenant
  AND u.project_id=project AND u.asset_version_id=p_asset_version
  AND u.document_id=p_document AND u.artifact_id=p_artifact
  AND u.sha256=p_sha AND u.state='ready' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'V2_DRAFT_UPLOAD_NOT_READY' USING ERRCODE='23514';END IF;
 IF p_layer_document IS NOT NULL THEN
  IF p_layer_artifact IS NULL OR p_layer_document=p_document
   OR p_layer_document IS NOT DISTINCT FROM p_base_document
   OR coalesce(p_layer_sha,'') !~ '^[0-9a-f]{64}$' OR p_layer_refs IS NULL
   OR p_refs IS NULL OR jsonb_typeof(p_refs)<>'array' OR NOT EXISTS(
    SELECT 1 FROM jsonb_array_elements(p_refs) x
    WHERE x->>'artifact_id'=p_layer_artifact::text AND x->>'sha256'=p_layer_sha) THEN
   RAISE EXCEPTION 'V2_DRAFT_LAYER_INVALID' USING ERRCODE='22023';
  END IF;
 ELSIF p_layer_artifact IS NOT NULL OR p_layer_sha IS NOT NULL OR p_layer_refs IS NOT NULL THEN
  RAISE EXCEPTION 'V2_DRAFT_LAYER_INVALID' USING ERRCODE='22023';
 END IF;
 IF p_layer_document IS NOT NULL THEN
  PERFORM 1 FROM photo.v2_draft_uploads u WHERE u.tenant_id=p_tenant
   AND u.project_id=project AND u.asset_version_id=p_asset_version
   AND u.document_id=p_layer_document AND u.artifact_id=p_layer_artifact
   AND u.sha256=p_layer_sha AND u.state='ready' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'V2_DRAFT_LAYER_NOT_READY' USING ERRCODE='23514';END IF;
  INSERT INTO photo.v2_documents(id,tenant_id,project_id,stream_id,version_no,document_type,artifact_id,sha256)
   VALUES(p_layer_document,p_tenant,project,stream.id,next_version,'LayerStack',p_layer_artifact,p_layer_sha);
  PERFORM photo.register_v2_document_refs(p_tenant,project,p_layer_document,p_layer_refs);
  next_version:=next_version+1;
 END IF;
 INSERT INTO photo.v2_documents(id,tenant_id,project_id,stream_id,version_no,document_type,artifact_id,sha256)
  VALUES(p_document,p_tenant,project,stream.id,next_version,'EditingRecipeV3',p_artifact,p_sha);
 PERFORM photo.register_v2_document_refs(p_tenant,project,p_document,p_refs);
 UPDATE photo.v2_document_streams SET current_document_id=p_document
  WHERE tenant_id=p_tenant AND id=stream.id RETURNING * INTO stream;
 RETURN jsonb_build_object('id',stream.id,'revision',stream.revision::text,'document_id',p_document);
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.replace_v2_draft(uuid,uuid,bigint,uuid,uuid,text,uuid,uuid,jsonb,uuid,uuid,text,jsonb,uuid,uuid,text,jsonb) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.replace_v2_draft(uuid,uuid,bigint,uuid,uuid,text,uuid,uuid,jsonb,uuid,uuid,text,jsonb,uuid,uuid,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.replace_v2_draft(uuid,uuid,bigint,uuid,uuid,text,uuid,uuid,jsonb,uuid,uuid,text,jsonb,uuid,uuid,text,jsonb) TO photo_api;

-- Preserve the layer-free call shape for existing clients.
-- +goose StatementBegin
CREATE FUNCTION photo.replace_v2_draft(p_tenant uuid,p_asset_version uuid,p_expected bigint,
 p_document uuid,p_artifact uuid,p_sha text,p_actor uuid,p_session uuid,p_refs jsonb,
 p_base_document uuid,p_base_artifact uuid,p_base_sha text,p_base_refs jsonb) RETURNS jsonb
LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
 SELECT photo.replace_v2_draft(p_tenant,p_asset_version,p_expected,p_document,
  p_artifact,p_sha,p_actor,p_session,p_refs,p_base_document,p_base_artifact,
  p_base_sha,p_base_refs,NULL::uuid,NULL::uuid,NULL::text,NULL::jsonb)
$$;
-- +goose StatementEnd
ALTER FUNCTION photo.replace_v2_draft(uuid,uuid,bigint,uuid,uuid,text,uuid,uuid,jsonb,uuid,uuid,text,jsonb) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.replace_v2_draft(uuid,uuid,bigint,uuid,uuid,text,uuid,uuid,jsonb,uuid,uuid,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.replace_v2_draft(uuid,uuid,bigint,uuid,uuid,text,uuid,uuid,jsonb,uuid,uuid,text,jsonb) TO photo_api;

-- Source: 00196_draft_approval.sql
-- FrozenRecipe bytes are produced and validated by the service before this DB TX.
-- +goose StatementBegin
CREATE FUNCTION photo.approve_v2_draft(
 p_tenant uuid,p_asset_version uuid,p_expected bigint,p_document uuid,p_actor uuid,p_session uuid,
 p_resolved_artifact uuid,p_resolved_sha text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE project uuid; asset uuid; latest_version uuid; stream photo.v2_document_streams%ROWTYPE;
 recipe photo.v2_documents%ROWTYPE; approval photo.v2_document_approvals%ROWTYPE;
BEGIN
 IF p_tenant IS NULL OR p_asset_version IS NULL OR p_document IS NULL OR p_actor IS NULL
  OR p_session IS NULL OR p_resolved_artifact IS NULL OR p_expected IS NULL OR p_expected<1
  OR coalesce(p_resolved_sha,'') !~ '^[0-9a-f]{64}$' THEN
  RAISE EXCEPTION 'V2_APPROVAL_INVALID' USING ERRCODE='22023';
 END IF;
 PERFORM id FROM photo.tenants WHERE id=p_tenant AND status='active' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'V2_TENANT_UNAVAILABLE' USING ERRCODE='42501';END IF;
 SELECT a.project_id,a.id INTO project,asset FROM photo.asset_versions v
 JOIN photo.assets a ON a.tenant_id=v.tenant_id AND a.id=v.asset_id
 WHERE v.tenant_id=p_tenant AND v.id=p_asset_version AND v.review_state='accepted'
  AND a.deleted_at IS NULL AND a.upload_state='verified'
  FOR UPDATE OF a FOR SHARE OF v;
 IF project IS NULL OR NOT photo.v2_editor_authorized(p_tenant,project,p_actor,p_session) THEN
  RAISE EXCEPTION 'V2_APPROVAL_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 SELECT id INTO latest_version FROM photo.asset_versions
  WHERE tenant_id=p_tenant AND asset_id=asset ORDER BY version_no DESC LIMIT 1;
 IF latest_version IS DISTINCT FROM p_asset_version THEN
  RAISE EXCEPTION 'V2_APPROVAL_SOURCE_STALE' USING ERRCODE='40001';
 END IF;
 SELECT * INTO stream FROM photo.v2_document_streams
  WHERE tenant_id=p_tenant AND project_id=project AND asset_version_id=p_asset_version
   AND stream_type='draft' FOR UPDATE;
 IF NOT FOUND OR stream.current_document_id IS DISTINCT FROM p_document THEN
  RAISE EXCEPTION 'V2_APPROVAL_DOCUMENT_CONFLICT' USING ERRCODE='40001';
 END IF;
 SELECT * INTO recipe FROM photo.v2_documents
  WHERE tenant_id=p_tenant AND project_id=project AND stream_id=stream.id
   AND id=p_document AND document_type='EditingRecipeV3';
 IF NOT FOUND OR NOT EXISTS(
  SELECT 1 FROM photo.v2_draft_uploads u JOIN photo.artifacts a
   ON a.tenant_id=u.tenant_id AND a.id=u.artifact_id AND a.sha256=u.sha256
  WHERE u.tenant_id=p_tenant AND u.project_id=project
   AND u.asset_version_id=p_asset_version AND u.document_id<>p_document
   AND u.artifact_id=p_resolved_artifact AND u.sha256=p_resolved_sha
   AND u.state='ready' AND a.state='ready' AND a.output_role='document'
   AND a.media_type='application/json' AND a.object_version=u.object_version
   AND a.verified_at IS NOT NULL
   AND (a.expires_at IS NULL OR a.expires_at>clock_timestamp())) THEN
  RAISE EXCEPTION 'V2_APPROVAL_ARTIFACT_INVALID' USING ERRCODE='23514';
 END IF;
 SELECT * INTO approval FROM photo.v2_document_approvals
  WHERE tenant_id=p_tenant AND document_id=p_document;
 IF FOUND THEN
  IF stream.approved_document_id IS DISTINCT FROM p_document
   OR approval.resolved_artifact_id<>p_resolved_artifact OR approval.recipe_sha<>recipe.sha256 THEN
   RAISE EXCEPTION 'V2_APPROVAL_REPLAY_CONFLICT' USING ERRCODE='40001';
  END IF;
  RETURN jsonb_build_object('id',stream.id,'revision',stream.revision::text,
   'document_id',p_document,'approval_id',approval.id);
 END IF;
 IF stream.revision<>p_expected THEN
  RAISE EXCEPTION 'V2_APPROVAL_REVISION_CONFLICT' USING ERRCODE='40001';
 END IF;
 INSERT INTO photo.v2_document_approvals(tenant_id,project_id,document_id,actor_id,recipe_sha,resolved_artifact_id)
  VALUES(p_tenant,project,p_document,p_actor,recipe.sha256,p_resolved_artifact) RETURNING * INTO approval;
 UPDATE photo.v2_document_streams SET approved_document_id=p_document
  WHERE tenant_id=p_tenant AND id=stream.id RETURNING * INTO stream;
 INSERT INTO photo.audit_log(tenant_id,actor_type,actor_id,action,resource_type,
  resource_id,request_id,details)
 VALUES(p_tenant,'user',p_actor,'v2_draft.approved','v2_document',p_document,
  gen_random_uuid(),jsonb_build_object('approval_id',approval.id,
   'stream_id',stream.id,'asset_version_id',p_asset_version,
   'recipe_sha',recipe.sha256,'resolved_artifact_id',p_resolved_artifact));
 RETURN jsonb_build_object('id',stream.id,'revision',stream.revision::text,
  'document_id',p_document,'approval_id',approval.id);
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.approve_v2_draft(uuid,uuid,bigint,uuid,uuid,uuid,uuid,text) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.approve_v2_draft(uuid,uuid,bigint,uuid,uuid,uuid,uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.approve_v2_draft(uuid,uuid,bigint,uuid,uuid,uuid,uuid,text) TO photo_api;

-- Source: 00196_capabilities.sql
-- Merge into migration 00196 only after the rest of V21 is wired and tested.
-- qualified_operations[operation] is an array of backend names, not an object.
-- +goose StatementBegin
CREATE FUNCTION photo.tenant_capabilities_evidence()
RETURNS TABLE(operation text,resource_class text,model_id text,
              supported_backends jsonb,available_backends jsonb,evidence jsonb)
LANGUAGE sql SECURITY DEFINER STABLE SET search_path=pg_catalog,photo AS $$
 WITH tenant_context AS (
  SELECT nullif(current_setting('app.tenant_id',true),'')::uuid AS tenant_id
 ), eligible AS (
  SELECT DISTINCT ON (op.operation,backend.value)
   op.operation,backend.value AS backend,n.doctor_report_sha256,w.lock_id,w.certificate_sha256
  FROM tenant_context tc
  JOIN photo.worker_registrations w ON w.tenant_id=tc.tenant_id
   AND w.enabled AND w.last_seen>current_timestamp-interval '30 seconds'
   AND w.certificate_sha256 IS NOT NULL
  JOIN photo.resource_nodes n ON n.node_id=w.node_id
   AND n.enabled AND n.reported_at>current_timestamp-interval '30 seconds'
   AND n.doctor_report_sha256 IS NOT NULL
  JOIN photo.operation_registry op ON w.resource_classes ? op.resource_class
  CROSS JOIN LATERAL jsonb_array_elements_text(
   CASE WHEN jsonb_typeof(w.qualified_operations->op.operation)='array'
    THEN w.qualified_operations->op.operation ELSE '[]'::jsonb END) backend(value)
  WHERE w.backends ? backend.value AND op.backends ? backend.value
   AND (op.model_id IS NULL OR w.lock_id ~ '^[0-9a-f]{64}$')
  ORDER BY op.operation,backend.value,n.doctor_report_sha256,w.worker_id
 )
 SELECT op.operation,op.resource_class,op.model_id,op.backends,
  coalesce((SELECT jsonb_agg(e.backend ORDER BY e.backend)
            FROM eligible e WHERE e.operation=op.operation),'[]'::jsonb),
  coalesce((SELECT jsonb_agg(jsonb_build_object(
             'backend',e.backend,'doctor_report_sha256',e.doctor_report_sha256,
             'model_lock_id',CASE WHEN op.model_id IS NULL THEN NULL ELSE e.lock_id END,
             'worker_certificate_sha256',e.certificate_sha256) ORDER BY e.backend)
            FROM eligible e WHERE e.operation=op.operation),'[]'::jsonb)
 FROM photo.operation_registry op ORDER BY op.operation
$$;
-- +goose StatementEnd
ALTER FUNCTION photo.tenant_capabilities_evidence() OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.tenant_capabilities_evidence() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.tenant_capabilities_evidence() TO photo_api;

-- Source: 00196_gc_refs.sql
-- Every V21 artifact-bearing row holds its bytes for its own lifecycle.
-- This helper must be incorporated into both artifact_has_references and the
-- claim_artifact_gc candidate predicate in the final migration.
-- +goose StatementBegin
CREATE FUNCTION photo.v2_artifact_has_references(p_tenant uuid,p_artifact uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
 SELECT
  EXISTS(SELECT FROM photo.v2_documents x WHERE x.tenant_id=p_tenant AND x.artifact_id=p_artifact)
  OR EXISTS(SELECT FROM photo.v2_document_refs x WHERE x.tenant_id=p_tenant AND x.artifact_id=p_artifact)
  OR EXISTS(SELECT FROM photo.v2_artifact_links x WHERE x.tenant_id=p_tenant AND x.artifact_id=p_artifact)
  OR EXISTS(SELECT FROM photo.v2_task_inputs x WHERE x.tenant_id=p_tenant AND x.artifact_id=p_artifact)
  OR EXISTS(SELECT FROM photo.v2_document_approvals x WHERE x.tenant_id=p_tenant AND x.resolved_artifact_id=p_artifact)
  OR EXISTS(SELECT FROM photo.v2_review_batches x WHERE x.tenant_id=p_tenant AND x.decisions_artifact_id=p_artifact)
  OR EXISTS(SELECT FROM photo.model_qualifications x WHERE x.tenant_id=p_tenant AND x.report_artifact_id=p_artifact)
  OR EXISTS(SELECT FROM photo.v2_draft_uploads x WHERE x.tenant_id=p_tenant AND x.artifact_id=p_artifact AND x.state='ready')
$$;
-- +goose StatementEnd
ALTER FUNCTION photo.v2_artifact_has_references(uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.v2_artifact_has_references(uuid,uuid) FROM PUBLIC;

-- Source: 00196_gc_integration.sql
-- Merge after 00196_gc_refs.sql. Existing GC lock/detach semantics preserved.
-- +goose StatementBegin
CREATE OR REPLACE FUNCTION photo.artifact_has_references(p_tenant uuid,p_artifact uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$ SELECT
 EXISTS(SELECT FROM photo.artifact_leases r WHERE r.tenant_id=p_tenant AND r.artifact_id=p_artifact AND r.expires_at>clock_timestamp()) OR
 EXISTS(SELECT FROM photo.assets r WHERE r.tenant_id=p_tenant AND r.original_artifact_id=p_artifact) OR EXISTS(SELECT FROM photo.asset_versions r WHERE r.tenant_id=p_tenant AND r.master_artifact_id=p_artifact) OR
 EXISTS(SELECT FROM photo.upload_sessions r WHERE r.tenant_id=p_tenant AND r.staging_artifact_id=p_artifact) OR EXISTS(SELECT FROM photo.style_versions r WHERE r.tenant_id=p_tenant AND r.export_artifact_id=p_artifact) OR
 EXISTS(SELECT FROM photo.style_asset_bindings r WHERE r.tenant_id=p_tenant AND r.artifact_id=p_artifact) OR EXISTS(SELECT FROM photo.training_pairs r WHERE r.tenant_id=p_tenant AND r.ignore_mask_artifact_id=p_artifact) OR
 EXISTS(SELECT FROM photo.snapshots r WHERE r.tenant_id=p_tenant AND r.artifact_id=p_artifact) OR EXISTS(SELECT FROM photo.snapshot_items r WHERE r.tenant_id=p_tenant AND r.artifact_id=p_artifact) OR
 EXISTS(SELECT FROM photo.tasks r WHERE r.tenant_id=p_tenant AND r.params_artifact_id=p_artifact) OR EXISTS(SELECT FROM photo.reviews r WHERE r.tenant_id=p_tenant AND (r.candidate_artifact_id=p_artifact OR r.base_artifact_id=p_artifact)) OR
 EXISTS(SELECT FROM photo.derivatives r WHERE r.tenant_id=p_tenant AND r.artifact_id=p_artifact) OR EXISTS(SELECT FROM photo.exports r WHERE r.tenant_id=p_tenant AND r.artifact_id=p_artifact) OR
 EXISTS(SELECT FROM photo.download_job_items r WHERE r.tenant_id=p_tenant AND r.artifact_id=p_artifact) OR EXISTS(SELECT FROM photo.download_volumes r WHERE r.tenant_id=p_tenant AND (r.artifact_id=p_artifact OR r.manifest_artifact_id=p_artifact)) OR
 EXISTS(SELECT FROM photo.download_intents r WHERE r.tenant_id=p_tenant AND r.artifact_id=p_artifact) OR photo.v2_artifact_has_references(p_tenant,p_artifact) $$;
-- +goose StatementEnd
ALTER FUNCTION photo.artifact_has_references(uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.artifact_has_references(uuid,uuid) FROM PUBLIC;

-- +goose StatementBegin
CREATE OR REPLACE FUNCTION photo.claim_artifact_gc()
RETURNS TABLE(artifact_id uuid,gc_token uuid,tenant_id uuid,bucket text,object_key text,object_version text,sha256 text,bytes bigint,media_type text)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE a photo.artifacts%ROWTYPE;token uuid:=gen_random_uuid();
BEGIN
 SELECT x.* INTO a FROM photo.artifacts x WHERE x.state='ready' AND x.expires_at<=clock_timestamp()
 AND EXISTS(SELECT FROM photo.tenants tenant WHERE tenant.id=x.tenant_id AND tenant.status='active')
 AND x.object_version IS NOT NULL AND x.object_version NOT IN ('','null')
 AND NOT EXISTS(SELECT FROM photo.artifact_leases l WHERE l.tenant_id=x.tenant_id AND l.artifact_id=x.id AND l.expires_at>clock_timestamp())
 AND NOT EXISTS(SELECT FROM photo.assets r WHERE r.tenant_id=x.tenant_id AND r.original_artifact_id=x.id)
 AND NOT EXISTS(SELECT FROM photo.asset_versions r WHERE r.tenant_id=x.tenant_id AND r.master_artifact_id=x.id)
 AND NOT EXISTS(SELECT FROM photo.upload_sessions r WHERE r.tenant_id=x.tenant_id AND r.staging_artifact_id=x.id)
 AND NOT EXISTS(SELECT FROM photo.style_versions r WHERE r.tenant_id=x.tenant_id AND r.export_artifact_id=x.id)
 AND NOT EXISTS(SELECT FROM photo.style_asset_bindings r WHERE r.tenant_id=x.tenant_id AND r.artifact_id=x.id)
 AND NOT EXISTS(SELECT FROM photo.training_pairs r WHERE r.tenant_id=x.tenant_id AND r.ignore_mask_artifact_id=x.id)
 AND NOT EXISTS(SELECT FROM photo.snapshots r WHERE r.tenant_id=x.tenant_id AND r.artifact_id=x.id)
 AND NOT EXISTS(SELECT FROM photo.snapshot_items r WHERE r.tenant_id=x.tenant_id AND r.artifact_id=x.id)
 AND NOT EXISTS(SELECT FROM photo.tasks r WHERE r.tenant_id=x.tenant_id AND r.params_artifact_id=x.id)
 AND NOT EXISTS(SELECT FROM photo.reviews r WHERE r.tenant_id=x.tenant_id AND (r.candidate_artifact_id=x.id OR r.base_artifact_id=x.id))
 AND NOT EXISTS(SELECT FROM photo.download_job_items r JOIN photo.download_jobs j ON j.tenant_id=r.tenant_id AND j.id=r.download_job_id WHERE r.tenant_id=x.tenant_id AND r.artifact_id=x.id AND (j.expires_at IS NULL OR j.expires_at>clock_timestamp()))
 AND NOT EXISTS(SELECT FROM photo.download_volumes r JOIN photo.download_jobs j ON j.tenant_id=r.tenant_id AND j.id=r.download_job_id WHERE r.tenant_id=x.tenant_id AND (r.artifact_id=x.id OR r.manifest_artifact_id=x.id) AND (j.expires_at IS NULL OR j.expires_at>clock_timestamp()))
 AND NOT photo.v2_artifact_has_references(x.tenant_id,x.id)
 ORDER BY x.expires_at,x.id LIMIT 1 FOR UPDATE SKIP LOCKED;
 IF NOT FOUND THEN RETURN;END IF;
 UPDATE photo.derivatives SET artifact_id=NULL,status='queued',task_id=NULL WHERE tenant_id=a.tenant_id AND artifact_id=a.id;
 UPDATE photo.exports SET artifact_id=NULL,status='queued',task_id=NULL WHERE tenant_id=a.tenant_id AND artifact_id=a.id;
 UPDATE photo.download_jobs j SET status='expired' WHERE j.tenant_id=a.tenant_id AND j.expires_at<=clock_timestamp() AND EXISTS(SELECT FROM photo.download_volumes v WHERE v.tenant_id=j.tenant_id AND v.download_job_id=j.id AND (v.artifact_id=a.id OR v.manifest_artifact_id=a.id));
 DELETE FROM photo.download_intents WHERE tenant_id=a.tenant_id AND artifact_id=a.id;
 UPDATE photo.download_job_items r SET artifact_id=NULL,sha256=NULL,bytes=NULL WHERE r.tenant_id=a.tenant_id AND r.artifact_id=a.id AND EXISTS(SELECT FROM photo.download_jobs j WHERE j.tenant_id=r.tenant_id AND j.id=r.download_job_id AND j.status='expired');
 UPDATE photo.download_volumes r SET artifact_id=NULL,manifest_artifact_id=NULL,status='expired' WHERE r.tenant_id=a.tenant_id AND (r.artifact_id=a.id OR r.manifest_artifact_id=a.id) AND EXISTS(SELECT FROM photo.download_jobs j WHERE j.tenant_id=r.tenant_id AND j.id=r.download_job_id AND j.status='expired');
 IF photo.artifact_has_references(a.tenant_id,a.id) THEN RAISE EXCEPTION 'ARTIFACT_GC_DETACH_INCOMPLETE' USING ERRCODE='40001';END IF;
 UPDATE photo.artifacts SET state='deleting',gc_token=token,gc_lease_until=clock_timestamp()+interval '60 seconds' WHERE id=a.id;
 RETURN QUERY SELECT a.id,token,a.tenant_id,a.bucket,a.object_key,a.object_version,a.sha256,a.bytes,a.media_type;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.claim_artifact_gc() OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.claim_artifact_gc() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.claim_artifact_gc() TO photo_maintenance;

-- Source: 00196_input_closure_gate.sql
-- A V2 task is dispatchable only after the trusted compiler has persisted
-- its exact input inventory and transport metadata. The worker still verifies
-- manifest/chunk content and the gateway checks every requested artifact.
-- +goose StatementBegin
CREATE FUNCTION photo.v2_input_closure_ready(p_task uuid) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE t photo.tasks%ROWTYPE; manifest jsonb; ref jsonb; direct_count integer; entry_count integer;
BEGIN
 SELECT * INTO t FROM photo.tasks WHERE id=p_task;
 IF NOT FOUND OR jsonb_typeof(t.inputs) IS DISTINCT FROM 'array'
  OR (jsonb_typeof(t.inputs)='array' AND jsonb_array_length(t.inputs) NOT BETWEEN 1 AND 128)
  OR t.execution_profile->>'renderer_version' IS DISTINCT FROM 'v2.2'
  OR t.execution_profile->>'contracts_sha' IS DISTINCT FROM
   '4004dd5e69d67835b7d295bfcebded5c006125256c2f6047fd11b2f2dca0f1b4' THEN
  RETURN false;
 END IF;
 IF coalesce(t.execution_profile->>'v2_entry_count','') !~ '^[1-9][0-9]{0,6}$'
  OR coalesce(t.execution_profile->>'v2_entries_sha','') !~ '^[0-9a-f]{64}$' THEN RETURN false; END IF;
 entry_count:=(t.execution_profile->>'v2_entry_count')::integer;
 IF entry_count>1000000 THEN RETURN false; END IF;
 manifest:=t.execution_profile->'v2_input_manifest';
 IF jsonb_typeof(manifest) IS DISTINCT FROM 'object' OR (manifest-'artifact_id'-'sha256')<>'{}'::jsonb
  OR manifest->>'artifact_id' IS NULL OR manifest->>'sha256' IS NULL
  OR manifest->>'sha256' !~ '^[0-9a-f]{64}$' THEN
  RETURN false;
 END IF;
 SELECT count(*) INTO direct_count FROM jsonb_array_elements(t.inputs) AS x(ref)
  WHERE x.ref=manifest;
 IF direct_count<>1 THEN RETURN false; END IF;
 IF NOT EXISTS(SELECT 1 FROM photo.runs r JOIN photo.v2_workflows w
  ON w.tenant_id=r.tenant_id AND w.run_id=r.id
  WHERE r.tenant_id=t.tenant_id AND r.id=t.run_id AND r.kind='v2'
   AND w.renderer_version='v2.2') THEN RETURN false; END IF;
 IF (SELECT count(*) FROM photo.v2_task_inputs i WHERE i.tenant_id=t.tenant_id AND i.task_id=t.id
     AND i.contract='InputClosureManifest' AND i.artifact_id::text=manifest->>'artifact_id'
     AND i.sha256=manifest->>'sha256')<>1 THEN RETURN false; END IF;
 IF (SELECT count(*) FROM photo.v2_task_inputs i WHERE i.tenant_id=t.tenant_id AND i.task_id=t.id
     AND i.contract='InputClosureChunk')<>(entry_count+511)/512 THEN RETURN false; END IF;
 IF (SELECT count(*) FROM photo.v2_task_inputs i WHERE i.tenant_id=t.tenant_id AND i.task_id=t.id
     AND i.contract NOT IN ('InputClosureManifest','InputClosureChunk'))<>entry_count THEN
  RETURN false;
 END IF;
 FOR ref IN SELECT value FROM jsonb_array_elements(t.inputs) LOOP
  IF jsonb_typeof(ref)<>'object' OR (ref-'artifact_id'-'sha256')<>'{}'::jsonb
   OR ref->>'artifact_id' IS NULL OR ref->>'sha256' IS NULL
   OR ref->>'sha256' !~ '^[0-9a-f]{64}$' THEN
   RETURN false;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM photo.v2_task_inputs i
   WHERE i.tenant_id=t.tenant_id AND i.task_id=t.id
    AND i.artifact_id::text=ref->>'artifact_id' AND i.sha256=ref->>'sha256') THEN
   RETURN false;
  END IF;
 END LOOP;
 RETURN true;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.v2_input_closure_ready(uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.v2_input_closure_ready(uuid) FROM PUBLIC;

-- Source: 00196_task_input_registration.sql
-- The compiler calls batches and seal in one DB transaction after immutable
-- transport objects have been published. No worker or API role can write rows.
-- +goose StatementBegin
CREATE FUNCTION photo.register_v2_task_input_batch(
 p_tenant uuid,p_run uuid,p_task uuid,p_first integer,p_rows jsonb)
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE t photo.tasks%ROWTYPE; r photo.runs%ROWTYPE; project uuid;
 next_ordinal integer; prior uuid; item jsonb; ref jsonb; aid uuid; ordinal integer:=p_first;
BEGIN
 IF p_tenant IS NULL OR p_run IS NULL OR p_task IS NULL OR p_first IS NULL OR p_first NOT BETWEEN 0 AND 999999
  OR jsonb_typeof(p_rows) IS DISTINCT FROM 'array' OR jsonb_array_length(p_rows) NOT BETWEEN 1 AND 512
  OR pg_column_size(p_rows)>1048576 OR p_first+jsonb_array_length(p_rows)>1000000 THEN
  RAISE EXCEPTION 'V2_INPUT_BATCH_INVALID' USING ERRCODE='22023';
 END IF;
 SELECT * INTO r FROM photo.runs WHERE tenant_id=p_tenant AND id=p_run FOR UPDATE;
 SELECT * INTO t FROM photo.tasks WHERE tenant_id=p_tenant AND run_id=p_run AND id=p_task FOR UPDATE;
 SELECT w.project_id INTO project FROM photo.v2_workflows w WHERE w.tenant_id=p_tenant
  AND w.run_id=p_run AND w.renderer_version='v2.2';
 IF t.id IS NULL OR r.id IS NULL OR project IS NULL OR r.kind<>'v2'
  OR r.status NOT IN ('draft','queued','running','waiting_review') OR r.graph_sealed
  OR r.cancel_requested OR t.cancel_requested OR t.state<>'blocked' OR t.attempt<>0
  OR t.execution_profile ? 'v2_input_manifest' THEN
  RAISE EXCEPTION 'V2_INPUT_TASK_UNAVAILABLE' USING ERRCODE='23514';
 END IF;
 SELECT coalesce(max(i.ordinal)+1,0) INTO next_ordinal FROM photo.v2_task_inputs i
  WHERE i.tenant_id=p_tenant AND i.task_id=p_task;
 IF next_ordinal<>p_first THEN RAISE EXCEPTION 'V2_INPUT_BATCH_GAP' USING ERRCODE='23514'; END IF;
 IF p_first>0 THEN
  SELECT i.artifact_id INTO prior FROM photo.v2_task_inputs i WHERE i.tenant_id=p_tenant
   AND i.task_id=p_task AND i.ordinal=p_first-1;
  IF prior IS NULL THEN RAISE EXCEPTION 'V2_INPUT_BATCH_GAP' USING ERRCODE='23514'; END IF;
 END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_rows) LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR (item-'ref'-'contract')<>'{}'::jsonb
   OR jsonb_typeof(item->'ref') IS DISTINCT FROM 'object'
   OR ((item->'ref')-'artifact_id'-'sha256')<>'{}'::jsonb
   OR coalesce(item->'ref'->>'artifact_id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   OR coalesce(item->'ref'->>'sha256','') !~ '^[0-9a-f]{64}$'
   OR length(coalesce(item->>'contract','')) NOT BETWEEN 1 AND 120
   OR item->>'contract' IN ('InputClosureChunk','InputClosureManifest') THEN
   RAISE EXCEPTION 'V2_INPUT_BATCH_INVALID' USING ERRCODE='22023';
  END IF;
  ref:=item->'ref'; aid:=(ref->>'artifact_id')::uuid;
  IF prior IS NOT NULL AND aid<=prior THEN
   RAISE EXCEPTION 'V2_INPUT_ORDER_INVALID' USING ERRCODE='23514';
  END IF;
  INSERT INTO photo.v2_task_inputs(tenant_id,project_id,task_id,artifact_id,sha256,contract,ordinal)
  VALUES(p_tenant,project,p_task,aid,ref->>'sha256',item->>'contract',ordinal);
  prior:=aid; ordinal:=ordinal+1;
 END LOOP;
 RETURN ordinal-p_first;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.register_v2_task_input_batch(uuid,uuid,uuid,integer,jsonb) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.register_v2_task_input_batch(uuid,uuid,uuid,integer,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.register_v2_task_input_batch(uuid,uuid,uuid,integer,jsonb) TO photo_scheduler;

-- +goose StatementBegin
CREATE FUNCTION photo.seal_v2_task_inputs(
 p_tenant uuid,p_run uuid,p_task uuid,p_manifest jsonb,p_chunks jsonb,
 p_entry_count integer,p_entries_sha text,p_direct_roots jsonb)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE t photo.tasks%ROWTYPE; r photo.runs%ROWTYPE; project uuid; item jsonb;
 n integer; ordinal integer:=0; manifest_id uuid; chunk_id uuid; seen uuid[]:='{}';
BEGIN
 IF p_tenant IS NULL OR p_run IS NULL OR p_task IS NULL OR p_entry_count IS NULL
  OR p_entry_count NOT BETWEEN 1 AND 1000000 OR p_entries_sha IS NULL
  OR p_entries_sha !~ '^[0-9a-f]{64}$'
  OR jsonb_typeof(p_manifest) IS DISTINCT FROM 'object'
  OR (p_manifest-'artifact_id'-'sha256')<>'{}'::jsonb
  OR coalesce(p_manifest->>'artifact_id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  OR coalesce(p_manifest->>'sha256','') !~ '^[0-9a-f]{64}$'
  OR jsonb_typeof(p_chunks) IS DISTINCT FROM 'array'
  OR jsonb_array_length(p_chunks) NOT BETWEEN 1 AND 1954
  OR jsonb_array_length(p_chunks)<>(p_entry_count+511)/512
  OR jsonb_typeof(p_direct_roots) IS DISTINCT FROM 'array'
  OR jsonb_array_length(p_direct_roots)>127 THEN
  RAISE EXCEPTION 'V2_INPUT_SEAL_INVALID' USING ERRCODE='22023';
 END IF;
 SELECT * INTO r FROM photo.runs WHERE tenant_id=p_tenant AND id=p_run FOR UPDATE;
 SELECT * INTO t FROM photo.tasks WHERE tenant_id=p_tenant AND run_id=p_run AND id=p_task FOR UPDATE;
 SELECT w.project_id INTO project FROM photo.v2_workflows w WHERE w.tenant_id=p_tenant
  AND w.run_id=p_run AND w.renderer_version='v2.2';
 IF t.id IS NULL OR r.id IS NULL OR project IS NULL OR r.kind<>'v2'
  OR r.status NOT IN ('draft','queued','running','waiting_review') OR r.graph_sealed
  OR r.cancel_requested OR t.cancel_requested OR t.state<>'blocked' OR t.attempt<>0
  OR t.execution_profile ? 'v2_input_manifest' THEN
  RAISE EXCEPTION 'V2_INPUT_TASK_UNAVAILABLE' USING ERRCODE='23514';
 END IF;
 SELECT count(*) INTO n FROM photo.v2_task_inputs i WHERE i.tenant_id=p_tenant AND i.task_id=p_task;
 IF n<>p_entry_count OR NOT EXISTS(SELECT 1 FROM photo.v2_task_inputs i
  WHERE i.tenant_id=p_tenant AND i.task_id=p_task AND i.ordinal=0)
  OR (SELECT max(i.ordinal) FROM photo.v2_task_inputs i
   WHERE i.tenant_id=p_tenant AND i.task_id=p_task)<>p_entry_count-1
  OR NOT EXISTS(SELECT 1 FROM photo.v2_task_inputs i WHERE i.tenant_id=p_tenant
   AND i.task_id=p_task AND i.artifact_id=t.params_artifact_id) THEN
  RAISE EXCEPTION 'V2_INPUT_ROWS_INCOMPLETE' USING ERRCODE='23514';
 END IF;
 manifest_id:=(p_manifest->>'artifact_id')::uuid;
 IF NOT EXISTS(SELECT 1 FROM photo.backend_documents d WHERE d.tenant_id=p_tenant
  AND d.run_id=p_run AND d.owner_id=p_task AND d.purpose='v2_input_manifest'
  AND d.state='ready' AND d.artifact_id=manifest_id AND d.sha256=p_manifest->>'sha256') THEN
  RAISE EXCEPTION 'V2_INPUT_MANIFEST_UNPUBLISHED' USING ERRCODE='23514';
 END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_chunks) LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR (item-'artifact_id'-'sha256')<>'{}'::jsonb
   OR coalesce(item->>'artifact_id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   OR coalesce(item->>'sha256','') !~ '^[0-9a-f]{64}$' THEN
   RAISE EXCEPTION 'V2_INPUT_SEAL_INVALID' USING ERRCODE='22023';
  END IF;
  chunk_id:=(item->>'artifact_id')::uuid;
  IF chunk_id=manifest_id OR chunk_id=ANY(seen) OR EXISTS(SELECT 1 FROM photo.v2_task_inputs i
   WHERE i.tenant_id=p_tenant AND i.task_id=p_task AND i.artifact_id=chunk_id) THEN
   RAISE EXCEPTION 'V2_INPUT_TRANSPORT_COLLISION' USING ERRCODE='23514';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM photo.backend_documents d WHERE d.tenant_id=p_tenant
   AND d.run_id=p_run AND d.owner_id=p_task AND d.purpose='v2_input_chunk_'||ordinal
   AND d.state='ready' AND d.artifact_id=chunk_id AND d.sha256=item->>'sha256') THEN
   RAISE EXCEPTION 'V2_INPUT_CHUNK_UNPUBLISHED' USING ERRCODE='23514';
  END IF;
  INSERT INTO photo.v2_task_inputs(tenant_id,project_id,task_id,artifact_id,sha256,contract,ordinal)
  VALUES(p_tenant,project,p_task,chunk_id,item->>'sha256','InputClosureChunk',1000000+ordinal);
  seen:=array_append(seen,chunk_id); ordinal:=ordinal+1;
 END LOOP;
 IF EXISTS(SELECT 1 FROM photo.v2_task_inputs i WHERE i.tenant_id=p_tenant
  AND i.task_id=p_task AND i.artifact_id=manifest_id) THEN
  RAISE EXCEPTION 'V2_INPUT_TRANSPORT_COLLISION' USING ERRCODE='23514';
 END IF;
 INSERT INTO photo.v2_task_inputs(tenant_id,project_id,task_id,artifact_id,sha256,contract,ordinal)
 VALUES(p_tenant,project,p_task,manifest_id,p_manifest->>'sha256','InputClosureManifest',1000000+ordinal);
 seen:=array_append(seen,manifest_id);
 FOR item IN SELECT value FROM jsonb_array_elements(p_direct_roots) LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR (item-'artifact_id'-'sha256')<>'{}'::jsonb
   OR coalesce(item->>'artifact_id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   OR coalesce(item->>'sha256','') !~ '^[0-9a-f]{64}$'
   OR NOT EXISTS(SELECT 1 FROM photo.v2_task_inputs i WHERE i.tenant_id=p_tenant
    AND i.task_id=p_task AND i.artifact_id=(item->>'artifact_id')::uuid
    AND i.sha256=item->>'sha256' AND i.contract NOT IN ('InputClosureChunk','InputClosureManifest')) THEN
   RAISE EXCEPTION 'V2_DIRECT_ROOT_INVALID' USING ERRCODE='23514';
  END IF;
 END LOOP;
 IF (SELECT count(*) FROM jsonb_array_elements(p_direct_roots) x) <>
  (SELECT count(DISTINCT x.value->>'artifact_id') FROM jsonb_array_elements(p_direct_roots) x) THEN
  RAISE EXCEPTION 'V2_DIRECT_ROOT_DUPLICATE' USING ERRCODE='23514';
 END IF;
 UPDATE photo.tasks SET inputs=jsonb_build_array(p_manifest)||p_direct_roots,
  execution_profile=execution_profile || jsonb_build_object(
   'renderer_version','v2.2',
   'contracts_sha','4004dd5e69d67835b7d295bfcebded5c006125256c2f6047fd11b2f2dca0f1b4',
   'v2_input_manifest',p_manifest,'v2_entry_count',p_entry_count,'v2_entries_sha',p_entries_sha)
 WHERE tenant_id=p_tenant AND id=p_task;
 IF NOT photo.v2_input_closure_ready(p_task) THEN
  RAISE EXCEPTION 'V2_INPUT_SEAL_INCOMPLETE' USING ERRCODE='23514';
 END IF;
 RETURN true;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.seal_v2_task_inputs(uuid,uuid,uuid,jsonb,jsonb,integer,text,jsonb) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.seal_v2_task_inputs(uuid,uuid,uuid,jsonb,jsonb,integer,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.seal_v2_task_inputs(uuid,uuid,uuid,jsonb,jsonb,integer,text,jsonb) TO photo_scheduler;

-- +goose StatementBegin
CREATE FUNCTION photo.guard_sealed_v2_task_inputs() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
BEGIN
 IF OLD.execution_profile ? 'v2_input_manifest' AND (
  NEW.inputs IS DISTINCT FROM OLD.inputs OR NEW.params_artifact_id IS DISTINCT FROM OLD.params_artifact_id
  OR NEW.input_digest IS DISTINCT FROM OLD.input_digest
  OR NEW.execution_profile->'v2_input_manifest' IS DISTINCT FROM OLD.execution_profile->'v2_input_manifest'
  OR NEW.execution_profile->'contracts_sha' IS DISTINCT FROM OLD.execution_profile->'contracts_sha'
  OR NEW.execution_profile->'renderer_version' IS DISTINCT FROM OLD.execution_profile->'renderer_version'
  OR NEW.execution_profile->'v2_entry_count' IS DISTINCT FROM OLD.execution_profile->'v2_entry_count'
  OR NEW.execution_profile->'v2_entries_sha' IS DISTINCT FROM OLD.execution_profile->'v2_entries_sha') THEN
  RAISE EXCEPTION 'V2_TASK_INPUTS_IMMUTABLE' USING ERRCODE='55000';
 END IF;
 RETURN NEW;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.guard_sealed_v2_task_inputs() OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.guard_sealed_v2_task_inputs() FROM PUBLIC;
CREATE TRIGGER v2_task_input_seal_guard BEFORE UPDATE ON photo.tasks
 FOR EACH ROW EXECUTE FUNCTION photo.guard_sealed_v2_task_inputs();

-- Source: 00196_draft_shell.sql
-- Create a draft shell before publishing task-scoped input transport objects.
-- This function is called only by the trusted V2 compiler after request auth;
-- it rechecks membership, project access, snapshot ownership and storage quota.
-- A failed call is atomic. Replays use the admission idempotency record, not a
-- second shell insert with the same run UUID.
-- +goose StatementBegin
CREATE FUNCTION photo.create_v2_draft_shell(
 p_tenant uuid,p_run uuid,p_workflow_id uuid,p_project uuid,p_snapshot uuid,p_actor uuid,
 p_workflow text,p_policy_sha text,p_config_sha text,p_config jsonb,
 p_tasks jsonb,p_edges jsonb,p_bytes bigint) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE tenant_row photo.tenants%ROWTYPE; usage_row photo.tenant_usage%ROWTYPE;
 project_row photo.projects%ROWTYPE; member_row photo.memberships%ROWTYPE;
 item jsonb; edge jsonb; task_id uuid; source_id uuid; target_id uuid;
 task_count integer; edge_count integer; limit_bytes numeric;
BEGIN
 IF p_tenant IS NULL OR p_run IS NULL OR p_workflow_id IS NULL OR p_project IS NULL OR p_snapshot IS NULL OR p_actor IS NULL
  OR p_policy_sha IS NULL OR p_policy_sha !~ '^[0-9a-f]{64}$'
  OR p_config_sha IS NULL OR p_config_sha !~ '^[0-9a-f]{64}$'
  OR p_workflow IS NULL OR p_workflow NOT IN
   ('session','learning','capture','semantic','delivery','interchange','provenance','preview')
  OR jsonb_typeof(p_config) IS DISTINCT FROM 'object'
  OR p_config->>'project_id' IS DISTINCT FROM p_project::text
  OR jsonb_typeof(p_tasks) IS DISTINCT FROM 'array'
  OR jsonb_typeof(p_edges) IS DISTINCT FROM 'array'
  OR p_bytes IS NULL OR p_bytes NOT BETWEEN 1 AND 9007199254740991 THEN RETURN false; END IF;
 task_count:=jsonb_array_length(p_tasks); edge_count:=jsonb_array_length(p_edges);
 IF task_count NOT BETWEEN 1 AND 5000 OR edge_count>20000
  OR pg_column_size(p_tasks)>8388608 OR pg_column_size(p_edges)>2097152 THEN RETURN false; END IF;
 SELECT * INTO tenant_row FROM photo.tenants WHERE id=p_tenant FOR UPDATE;
 SELECT * INTO usage_row FROM photo.tenant_usage WHERE tenant_id=p_tenant FOR UPDATE;
 SELECT * INTO project_row FROM photo.projects WHERE tenant_id=p_tenant AND id=p_project;
 SELECT * INTO member_row FROM photo.memberships WHERE tenant_id=p_tenant AND user_id=p_actor;
 IF tenant_row.id IS NULL OR tenant_row.status<>'active' OR usage_row.id IS NULL
  OR project_row.id IS NULL OR project_row.archived_at IS NOT NULL
  OR member_row.id IS NULL OR member_row.status<>'active'
  OR member_row.role NOT IN ('owner','admin','editor')
  OR (project_row.visibility='restricted' AND member_row.role NOT IN ('owner','admin')
   AND NOT EXISTS(SELECT 1 FROM photo.project_acl acl WHERE acl.tenant_id=p_tenant
    AND acl.project_id=p_project AND acl.user_id=p_actor AND acl.role='editor'))
  OR NOT EXISTS(SELECT 1 FROM photo.snapshots s WHERE s.tenant_id=p_tenant AND s.id=p_snapshot
   AND s.kind='v2' AND s.principal_type='user' AND s.principal_id=p_actor
   AND (s.expires_at IS NULL OR s.expires_at>clock_timestamp()))
  OR EXISTS(SELECT 1 FROM photo.runs r WHERE r.tenant_id=p_tenant AND r.id=p_run) THEN RETURN false; END IF;
 limit_bytes:=(tenant_row.quotas->>'storage_bytes')::numeric;
 IF limit_bytes IS NULL OR usage_row.storage_bytes::numeric+usage_row.reserved_bytes+p_bytes>limit_bytes
  OR usage_row.storage_bytes::numeric+usage_row.reserved_bytes+p_bytes>9007199254740991 THEN RETURN false; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_tasks) LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object'
   OR (item-'id'-'node_key'-'operation'-'operation_version'-'resource_class'
    -'params_artifact_id'-'params_sha'-'input_digest'-'execution_profile')<>'{}'::jsonb
   OR coalesce(item->>'id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   OR coalesce(item->>'params_artifact_id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   OR coalesce(item->>'params_sha','') !~ '^[0-9a-f]{64}$'
   OR coalesce(item->>'input_digest','') !~ '^[0-9a-f]{64}$'
   OR length(coalesce(item->>'node_key','')) NOT BETWEEN 1 AND 256
   OR length(coalesce(item->>'operation','')) NOT BETWEEN 1 AND 120
   OR length(coalesce(item->>'operation_version','')) NOT BETWEEN 1 AND 64
   OR jsonb_typeof(item->'execution_profile') IS DISTINCT FROM 'object'
   OR item->'execution_profile' ? 'v2_input_manifest'
   OR coalesce(item->'execution_profile'->>'backend','') NOT IN ('cpu','cuda','mps')
   OR NOT EXISTS(SELECT 1 FROM photo.operation_registry op WHERE op.operation=item->>'operation'
    AND op.version=item->>'operation_version' AND op.resource_class=item->>'resource_class'
    AND op.backends ? (item->'execution_profile'->>'backend'))
   OR NOT EXISTS(SELECT 1 FROM photo.artifacts a WHERE a.tenant_id=p_tenant
    AND a.id=(item->>'params_artifact_id')::uuid AND a.sha256=item->>'params_sha'
    AND a.state='ready' AND a.media_type='application/json' AND a.object_version IS NOT NULL
    AND a.verified_at IS NOT NULL AND (a.expires_at IS NULL OR a.expires_at>clock_timestamp()))
   THEN RETURN false; END IF;
 END LOOP;
 FOR edge IN SELECT value FROM jsonb_array_elements(p_edges) LOOP
  IF jsonb_typeof(edge) IS DISTINCT FROM 'object'
   OR (edge-'prerequisite_id'-'dependent_id')<>'{}'::jsonb
   OR coalesce(edge->>'prerequisite_id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   OR coalesce(edge->>'dependent_id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   OR edge->>'prerequisite_id'=edge->>'dependent_id' THEN RETURN false; END IF;
 END LOOP;
 INSERT INTO photo.runs(id,tenant_id,kind,status,input_snapshot_id,config_snapshot,
  config_hash,created_by,failure_policy,graph_sealed)
 VALUES(p_run,p_tenant,'v2','draft',p_snapshot,p_config,p_config_sha,p_actor,'fail_fast',false);
 INSERT INTO photo.v2_workflows(id,tenant_id,project_id,run_id,input_snapshot_id,
  workflow_type,renderer_version,policy_sha)
 VALUES(p_workflow_id,p_tenant,p_project,p_run,p_snapshot,p_workflow,'v2.2',p_policy_sha);
 FOR item IN SELECT value FROM jsonb_array_elements(p_tasks) LOOP
  task_id:=(item->>'id')::uuid;
  INSERT INTO photo.tasks(id,tenant_id,run_id,node_key,operation,operation_version,
   resource_class,inputs,params_artifact_id,input_digest,execution_profile)
  VALUES(task_id,p_tenant,p_run,item->>'node_key',item->>'operation',item->>'operation_version',
   item->>'resource_class','[]'::jsonb,(item->>'params_artifact_id')::uuid,
   item->>'input_digest',item->'execution_profile');
 END LOOP;
 FOR edge IN SELECT value FROM jsonb_array_elements(p_edges) LOOP
  source_id:=(edge->>'prerequisite_id')::uuid; target_id:=(edge->>'dependent_id')::uuid;
  IF NOT EXISTS(SELECT 1 FROM photo.tasks t WHERE t.tenant_id=p_tenant AND t.run_id=p_run AND t.id=source_id)
   OR NOT EXISTS(SELECT 1 FROM photo.tasks t WHERE t.tenant_id=p_tenant AND t.run_id=p_run AND t.id=target_id)
   THEN RAISE EXCEPTION 'V2_EDGE_OUTSIDE_GRAPH' USING ERRCODE='23514'; END IF;
  INSERT INTO photo.task_edges(tenant_id,run_id,prerequisite_id,dependent_id,condition)
  VALUES(p_tenant,p_run,source_id,target_id,'success');
 END LOOP;
 INSERT INTO photo.quota_reservations(tenant_id,principal_type,principal_id,
  holder_type,holder_id,bytes,files,expires_at)
 VALUES(p_tenant,'user',p_actor,'run',p_run,p_bytes,0,clock_timestamp()+interval '1 hour');
 UPDATE photo.tenant_usage SET reserved_bytes=reserved_bytes+p_bytes WHERE tenant_id=p_tenant;
 RETURN true;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.create_v2_draft_shell(uuid,uuid,uuid,uuid,uuid,uuid,text,text,text,jsonb,jsonb,jsonb,bigint) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.create_v2_draft_shell(uuid,uuid,uuid,uuid,uuid,uuid,text,text,text,jsonb,jsonb,jsonb,bigint) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.create_v2_draft_shell(uuid,uuid,uuid,uuid,uuid,uuid,text,text,text,jsonb,jsonb,jsonb,bigint) TO photo_scheduler;

-- Source: 00196_pending_replay_guard.sql
-- A pending replay may resume publication only for the exact admitted shell.
-- Compiler drift under an unchanged request hash is a conflict, not a chance
-- to publish a different graph into the existing draft run.
-- +goose StatementBegin
CREATE FUNCTION photo.v2_pending_shell_matches(
 p_tenant uuid,p_run uuid,p_workflow uuid,p_project uuid,p_snapshot uuid,
 p_actor uuid,p_type text,p_policy_sha text,p_config_sha text,p_config jsonb,
 p_tasks jsonb,p_edges jsonb,p_bytes bigint) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
 SELECT jsonb_typeof(p_tasks)='array' AND jsonb_typeof(p_edges)='array'
 AND EXISTS(SELECT 1 FROM photo.runs r JOIN photo.v2_workflows w
  ON w.tenant_id=r.tenant_id AND w.run_id=r.id
  WHERE r.tenant_id=p_tenant AND r.id=p_run AND r.kind='v2'
   AND r.status='draft' AND NOT r.graph_sealed AND NOT r.cancel_requested
   AND r.input_snapshot_id=p_snapshot AND r.created_by=p_actor
   AND r.config_hash=p_config_sha AND r.config_snapshot=p_config
   AND w.id=p_workflow AND w.project_id=p_project
   AND w.workflow_type=p_type AND w.policy_sha=p_policy_sha)
 AND EXISTS(SELECT 1 FROM photo.quota_reservations q
  WHERE q.tenant_id=p_tenant AND q.holder_type='run' AND q.holder_id=p_run
   AND q.state='reserved' AND q.bytes=p_bytes)
 AND coalesce((SELECT jsonb_agg(value ORDER BY value->>'id')
  FROM jsonb_array_elements(p_tasks)), '[]'::jsonb) =
  coalesce((SELECT jsonb_agg(jsonb_build_object(
   'id',t.id,'node_key',t.node_key,'operation',t.operation,
   'operation_version',t.operation_version,'resource_class',t.resource_class,
   'params_artifact_id',t.params_artifact_id,'params_sha',a.sha256,
   'input_digest',t.input_digest,'execution_profile',t.execution_profile)
   ORDER BY t.id::text)
   FROM photo.tasks t JOIN photo.artifacts a
    ON a.tenant_id=t.tenant_id AND a.id=t.params_artifact_id
   WHERE t.tenant_id=p_tenant AND t.run_id=p_run), '[]'::jsonb)
 AND coalesce((SELECT jsonb_agg(value ORDER BY value->>'prerequisite_id',
   value->>'dependent_id') FROM jsonb_array_elements(p_edges)), '[]'::jsonb) =
  coalesce((SELECT jsonb_agg(jsonb_build_object(
   'prerequisite_id',e.prerequisite_id,'dependent_id',e.dependent_id)
   ORDER BY e.prerequisite_id::text,e.dependent_id::text)
   FROM photo.task_edges e WHERE e.tenant_id=p_tenant AND e.run_id=p_run
    AND e.condition='success'), '[]'::jsonb)
 AND NOT EXISTS(SELECT 1 FROM photo.task_edges e WHERE e.tenant_id=p_tenant
  AND e.run_id=p_run AND e.condition<>'success')
$$;
-- +goose StatementEnd
ALTER FUNCTION photo.v2_pending_shell_matches(uuid,uuid,uuid,uuid,uuid,uuid,text,text,text,jsonb,jsonb,jsonb,bigint)
 OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.v2_pending_shell_matches(uuid,uuid,uuid,uuid,uuid,uuid,text,text,text,jsonb,jsonb,jsonb,bigint)
 FROM PUBLIC;

-- Source: 00196_admission_idempotency.sql
-- Pending idempotency is committed with the draft shell. A replay resumes the
-- same run after transport publication crashes; only graph seal completes the
-- saved 202 JobTicket. Different request bytes under the same key conflict.
-- +goose StatementBegin
CREATE FUNCTION photo.begin_v2_admission(
 p_tenant uuid,p_run uuid,p_workflow_id uuid,p_project uuid,p_snapshot uuid,p_actor uuid,
 p_workflow text,p_policy_sha text,p_config_sha text,p_config jsonb,
 p_tasks jsonb,p_edges jsonb,p_bytes bigint,p_key text,p_request_sha text)
RETURNS TABLE(outcome text,run_id uuid)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE idem photo.idempotency_records%ROWTYPE; existing photo.runs%ROWTYPE;
 created boolean;
BEGIN
 IF p_tenant IS NULL OR p_run IS NULL OR p_actor IS NULL OR
  p_key IS NULL OR p_key COLLATE "C" !~ '^[!-~]{1,128}$' OR
  p_request_sha IS NULL OR p_request_sha !~ '^[0-9a-f]{64}$' THEN
  RAISE EXCEPTION 'V2_IDEMPOTENCY_INVALID' USING ERRCODE='22023';
 END IF;
 INSERT INTO photo.idempotency_records(tenant_id,principal_type,principal_id,
  route,key,request_hash,expires_at)
 VALUES(p_tenant,'user',p_actor,'V2.Admit',p_key,p_request_sha,
  clock_timestamp()+interval '24 hours')
 ON CONFLICT(tenant_id,principal_type,principal_id,route,key) DO NOTHING;
 SELECT * INTO idem FROM photo.idempotency_records x WHERE x.tenant_id=p_tenant
  AND x.principal_type='user' AND x.principal_id=p_actor
  AND x.route='V2.Admit' AND x.key=p_key FOR UPDATE;
 IF idem.id IS NULL THEN RAISE EXCEPTION 'V2_IDEMPOTENCY_MISSING' USING ERRCODE='23514'; END IF;
 IF idem.request_hash<>p_request_sha THEN
  RETURN QUERY SELECT 'conflict'::text,NULL::uuid; RETURN;
 END IF;
 IF idem.resource_id IS NOT NULL THEN
  SELECT * INTO existing FROM photo.runs r WHERE r.tenant_id=p_tenant
   AND r.id=idem.resource_id AND r.created_by=p_actor AND r.kind='v2';
  IF existing.id IS NULL THEN RAISE EXCEPTION 'V2_IDEMPOTENCY_CORRUPT' USING ERRCODE='23514'; END IF;
  IF idem.response_status=202 AND existing.graph_sealed THEN
   RETURN QUERY SELECT 'replayed'::text,existing.id; RETURN;
  END IF;
  IF idem.response_status IS NULL AND existing.status='draft' AND NOT existing.graph_sealed
   AND EXISTS(SELECT 1 FROM photo.quota_reservations q WHERE q.tenant_id=p_tenant
    AND q.holder_type='run' AND q.holder_id=existing.id AND q.state='reserved'
    AND q.expires_at>clock_timestamp()) THEN
   IF NOT photo.v2_pending_shell_matches(p_tenant,existing.id,p_workflow_id,
    p_project,p_snapshot,p_actor,p_workflow,p_policy_sha,p_config_sha,p_config,
    p_tasks,p_edges,p_bytes) THEN
    RETURN QUERY SELECT 'conflict'::text,existing.id; RETURN;
   END IF;
   RETURN QUERY SELECT 'pending'::text,existing.id; RETURN;
  END IF;
  RETURN QUERY SELECT 'expired'::text,existing.id; RETURN;
 END IF;
 SELECT photo.create_v2_draft_shell(p_tenant,p_run,p_workflow_id,p_project,p_snapshot,p_actor,
  p_workflow,p_policy_sha,p_config_sha,p_config,p_tasks,p_edges,p_bytes) INTO created;
 IF NOT created THEN RAISE EXCEPTION 'V2_DRAFT_REJECTED' USING ERRCODE='23514'; END IF;
 UPDATE photo.idempotency_records SET resource_id=p_run WHERE tenant_id=p_tenant AND id=idem.id;
 RETURN QUERY SELECT 'created'::text,p_run;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.begin_v2_admission(uuid,uuid,uuid,uuid,uuid,uuid,text,text,text,jsonb,jsonb,jsonb,bigint,text,text) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.begin_v2_admission(uuid,uuid,uuid,uuid,uuid,uuid,text,text,text,jsonb,jsonb,jsonb,bigint,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.begin_v2_admission(uuid,uuid,uuid,uuid,uuid,uuid,text,text,text,jsonb,jsonb,jsonb,bigint,text,text) TO photo_scheduler;

-- Read only the completed original ticket, never a draft placeholder.
-- +goose StatementBegin
CREATE FUNCTION photo.v2_admission_ticket(p_tenant uuid,p_actor uuid,p_key text,p_request_sha text)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
 SELECT i.response_body FROM photo.idempotency_records i
 JOIN photo.runs r ON r.tenant_id=i.tenant_id AND r.id=i.resource_id
 WHERE i.tenant_id=p_tenant AND i.principal_type='user' AND i.principal_id=p_actor
  AND i.route='V2.Admit' AND i.key=p_key AND i.request_hash=p_request_sha
  AND i.response_status=202 AND r.kind='v2' AND r.graph_sealed
$$;
-- +goose StatementEnd
ALTER FUNCTION photo.v2_admission_ticket(uuid,uuid,text,text) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.v2_admission_ticket(uuid,uuid,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.v2_admission_ticket(uuid,uuid,text,text) TO photo_scheduler;

-- Source: 00196_graph_seal.sql
-- Registration is explicit per package; legacy operations are never V2-capable
-- merely because their resource class and renderer happen to match.
ALTER TABLE photo.operation_registry ADD COLUMN v2_enabled boolean NOT NULL DEFAULT false;

-- Seal a complete, quota-backed graph, then activate only tasks without
-- prerequisites through the existing fenced bound-task activator.
-- +goose StatementBegin
CREATE FUNCTION photo.seal_v2_graph(p_tenant uuid,p_run uuid) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE r photo.runs%ROWTYPE; q photo.quota_reservations%ROWTYPE;
 task_count integer; edge_count integer; remaining uuid[]; removable uuid[]; root record;
 next_cursor bigint; event_id uuid; saved_count integer;
BEGIN
 IF p_tenant IS NULL OR p_run IS NULL THEN RETURN false; END IF;
 -- Match input-document admission's usage -> run -> task lock order.
 PERFORM id FROM photo.tenant_usage WHERE tenant_id=p_tenant FOR UPDATE;
 IF NOT FOUND THEN RETURN false; END IF;
 SELECT * INTO r FROM photo.runs WHERE tenant_id=p_tenant AND id=p_run FOR UPDATE;
 IF r.id IS NULL OR r.kind<>'v2' OR r.cancel_requested THEN RETURN false; END IF;
 IF r.graph_sealed THEN RETURN r.status IN ('queued','running','waiting_review'); END IF;
 IF r.status<>'draft' OR r.failure_policy<>'fail_fast' OR
  NOT EXISTS(SELECT 1 FROM photo.tenants tenant WHERE tenant.id=p_tenant AND tenant.status='active') OR
  NOT EXISTS(SELECT 1 FROM photo.v2_workflows w WHERE w.tenant_id=p_tenant AND w.run_id=p_run
   AND w.renderer_version='v2.2') OR
  EXISTS(SELECT 1 FROM photo.graph_expansions e WHERE e.tenant_id=p_tenant AND e.run_id=p_run
   AND e.state<>'closed') THEN RETURN false; END IF;
 SELECT * INTO q FROM photo.quota_reservations x WHERE x.tenant_id=p_tenant AND x.holder_type='run'
  AND x.holder_id=p_run AND x.state='reserved' AND x.expires_at>clock_timestamp() FOR UPDATE;
 IF q.id IS NULL OR q.bytes<=0 OR NOT EXISTS(SELECT 1 FROM photo.tenant_usage u
  WHERE u.tenant_id=p_tenant AND u.reserved_bytes>=q.bytes) THEN RETURN false; END IF;
 SELECT count(*) INTO task_count FROM photo.tasks t WHERE t.tenant_id=p_tenant AND t.run_id=p_run;
 SELECT count(*) INTO edge_count FROM photo.task_edges e WHERE e.tenant_id=p_tenant AND e.run_id=p_run;
 IF task_count NOT BETWEEN 1 AND 5000 OR edge_count>20000 THEN RETURN false; END IF;
 IF EXISTS(SELECT 1 FROM photo.tasks t WHERE t.tenant_id=p_tenant AND t.run_id=p_run AND (
  t.state<>'blocked' OR t.cancel_requested OR t.attempt<>0 OR
  NOT photo.v2_input_closure_ready(t.id) OR
  NOT EXISTS(SELECT 1 FROM photo.operation_registry op WHERE op.operation=t.operation
   AND op.version=t.operation_version AND op.v2_enabled
   AND op.resource_class=t.resource_class AND op.backends ? (t.execution_profile->>'backend')) OR
  NOT EXISTS(SELECT 1 FROM photo.operation_output_policies policy WHERE
   policy.operation=t.operation AND policy.version=t.operation_version
   AND policy.role='document' AND policy.media_types ? 'application/json'))) THEN RETURN false; END IF;
 IF EXISTS(SELECT 1 FROM photo.task_edges e WHERE e.tenant_id=p_tenant AND e.run_id=p_run
  AND e.condition<>'success') THEN RETURN false; END IF;
 SELECT array_agg(t.id ORDER BY t.id) INTO remaining FROM photo.tasks t
  WHERE t.tenant_id=p_tenant AND t.run_id=p_run;
 WHILE coalesce(array_length(remaining,1),0)>0 LOOP
  SELECT array_agg(node.id ORDER BY node.id) INTO removable FROM unnest(remaining) node(id)
   WHERE NOT EXISTS(SELECT 1 FROM photo.task_edges e WHERE e.tenant_id=p_tenant
    AND e.run_id=p_run AND e.dependent_id=node.id AND e.prerequisite_id=ANY(remaining));
  IF removable IS NULL THEN RETURN false; END IF;
  SELECT array_agg(node.id ORDER BY node.id) INTO remaining FROM unnest(remaining) node(id)
   WHERE node.id<>ALL(removable);
 END LOOP;
 UPDATE photo.runs SET graph_sealed=true,status='queued',revision=revision+1
  WHERE tenant_id=p_tenant AND id=p_run AND status='draft' AND NOT graph_sealed;
 IF NOT FOUND THEN RAISE EXCEPTION 'V2_GRAPH_SEAL_RACE' USING ERRCODE='40001'; END IF;
 FOR root IN SELECT t.id,t.input_digest,t.params_artifact_id FROM photo.tasks t
  WHERE t.tenant_id=p_tenant AND t.run_id=p_run AND NOT EXISTS(
   SELECT 1 FROM photo.task_edges e WHERE e.tenant_id=p_tenant AND e.run_id=p_run AND e.dependent_id=t.id)
  ORDER BY t.id LOOP
  IF NOT photo.activate_bound_task(root.id,root.input_digest,root.params_artifact_id) THEN
   RAISE EXCEPTION 'V2_ROOT_ACTIVATION_FAILED' USING ERRCODE='23514';
  END IF;
 END LOOP;
 INSERT INTO photo.tenant_event_cursors(tenant_id,last_cursor) VALUES(p_tenant,0)
  ON CONFLICT(tenant_id) DO NOTHING;
 UPDATE photo.tenant_event_cursors SET last_cursor=last_cursor+1
  WHERE tenant_id=p_tenant AND last_cursor<9007199254740991 RETURNING last_cursor INTO next_cursor;
 IF next_cursor IS NULL THEN RAISE EXCEPTION 'EVENT_CURSOR_EXHAUSTED' USING ERRCODE='23514'; END IF;
 INSERT INTO photo.run_events(tenant_id,cursor,run_id,principal_id,audience,type,payload)
 VALUES(p_tenant,next_cursor,p_run,r.created_by,'principal','v2.run.queued',
  jsonb_build_object('run_id',p_run,'status','queued','revision',r.revision+1));
 event_id:=gen_random_uuid();
 INSERT INTO photo.outbox(tenant_id,event_id,destination,routing_key,payload)
 VALUES(p_tenant,event_id,'photo.events.v1','v2.run.queued',
  jsonb_build_object('schema_version',1,'event_id',event_id,'type','v2.run.queued',
   'tenant_id',p_tenant,'run_id',p_run,'status','queued'));
 UPDATE photo.idempotency_records i SET response_status=202,
  response_body=jsonb_build_object('run_id',p_run,'workflow_id',
   (SELECT w.id FROM photo.v2_workflows w WHERE w.tenant_id=p_tenant AND w.run_id=p_run),
   'state','queued')
 WHERE i.tenant_id=p_tenant AND i.principal_type='user' AND i.principal_id=r.created_by
  AND i.route='V2.Admit' AND i.resource_id=p_run AND i.response_status IS NULL;
 GET DIAGNOSTICS saved_count = ROW_COUNT;
 IF saved_count>1 THEN RAISE EXCEPTION 'V2_IDEMPOTENCY_DUPLICATE' USING ERRCODE='23514'; END IF;
 RETURN true;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.seal_v2_graph(uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.seal_v2_graph(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.seal_v2_graph(uuid,uuid) TO photo_scheduler;

-- Source: 00196_draft_expiry.sql
-- An unsealed draft cannot have been dispatched. Once its run reservation
-- expires, cancel its blocked tasks and release that reservation atomically.
-- Pending transport uploads retain their own reservations until the existing
-- fenced backend-document cleanup confirms object deletion.
-- +goose StatementBegin
CREATE FUNCTION photo.expire_v2_draft(p_tenant uuid,p_run uuid) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE r photo.runs%ROWTYPE; q photo.quota_reservations%ROWTYPE;
 next_cursor bigint; event_id uuid;
BEGIN
 IF p_tenant IS NULL OR p_run IS NULL THEN RETURN false; END IF;
 PERFORM id FROM photo.tenant_usage WHERE tenant_id=p_tenant FOR UPDATE;
 IF NOT FOUND THEN RETURN false; END IF;
 SELECT * INTO r FROM photo.runs WHERE tenant_id=p_tenant AND id=p_run FOR UPDATE;
 IF r.id IS NULL OR r.kind<>'v2' OR r.status<>'draft' OR r.graph_sealed THEN RETURN false; END IF;
 SELECT * INTO q FROM photo.quota_reservations x WHERE x.tenant_id=p_tenant
  AND x.holder_type='run' AND x.holder_id=p_run AND x.state='reserved' FOR UPDATE;
 IF q.id IS NULL OR q.expires_at>clock_timestamp() OR q.bytes<=0
  OR EXISTS(SELECT 1 FROM photo.tasks t WHERE t.tenant_id=p_tenant AND t.run_id=p_run
   AND (t.state<>'blocked' OR t.attempt<>0 OR t.fencing_token<>0))
  OR r.revision>=9007199254740991 THEN RETURN false; END IF;
 UPDATE photo.tasks SET state='cancelled',cancel_requested=true,
  terminal_reason='v2_draft_expired',fencing_token=fencing_token+1
 WHERE tenant_id=p_tenant AND run_id=p_run AND state='blocked';
 UPDATE photo.tenant_usage SET reserved_bytes=reserved_bytes-q.bytes
  WHERE tenant_id=p_tenant AND reserved_bytes>=q.bytes;
 IF NOT FOUND THEN RAISE EXCEPTION 'V2_DRAFT_QUOTA_INCONSISTENT' USING ERRCODE='23514'; END IF;
 UPDATE photo.quota_reservations SET bytes=0,state='released',expires_at=clock_timestamp()
  WHERE tenant_id=p_tenant AND id=q.id;
 UPDATE photo.runs SET status='cancelled',cancel_requested=true,revision=revision+1
  WHERE tenant_id=p_tenant AND id=p_run;
 INSERT INTO photo.tenant_event_cursors(tenant_id,last_cursor) VALUES(p_tenant,0)
  ON CONFLICT(tenant_id) DO NOTHING;
 UPDATE photo.tenant_event_cursors SET last_cursor=last_cursor+1
  WHERE tenant_id=p_tenant AND last_cursor<9007199254740991 RETURNING last_cursor INTO next_cursor;
 IF next_cursor IS NULL THEN RAISE EXCEPTION 'EVENT_CURSOR_EXHAUSTED' USING ERRCODE='23514'; END IF;
 INSERT INTO photo.run_events(tenant_id,cursor,run_id,principal_id,audience,type,payload)
 VALUES(p_tenant,next_cursor,p_run,r.created_by,'principal','v2.run.cancelled',
  jsonb_build_object('run_id',p_run,'status','cancelled','reason','draft_expired'));
 event_id:=gen_random_uuid();
 INSERT INTO photo.outbox(tenant_id,event_id,destination,routing_key,payload)
 VALUES(p_tenant,event_id,'photo.events.v1','v2.run.cancelled',
  jsonb_build_object('schema_version',1,'event_id',event_id,'type','v2.run.cancelled',
   'tenant_id',p_tenant,'run_id',p_run,'status','cancelled','reason','draft_expired'));
 RETURN true;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.expire_v2_draft(uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.expire_v2_draft(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.expire_v2_draft(uuid,uuid) TO photo_maintenance;

-- Claim one expired draft at a time; the fenced function rechecks everything.
-- +goose StatementBegin
CREATE FUNCTION photo.expire_one_v2_draft() RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE candidate record;
BEGIN
 SELECT r.tenant_id,r.id INTO candidate FROM photo.runs r
 JOIN photo.quota_reservations q ON q.tenant_id=r.tenant_id
  AND q.holder_type='run' AND q.holder_id=r.id AND q.state='reserved'
 WHERE r.kind='v2' AND r.status='draft' AND NOT r.graph_sealed
  AND q.expires_at<=clock_timestamp()
 ORDER BY q.expires_at,r.id LIMIT 1;
 IF candidate.id IS NULL THEN RETURN false; END IF;
 RETURN photo.expire_v2_draft(candidate.tenant_id,candidate.id);
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.expire_one_v2_draft() OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.expire_one_v2_draft() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.expire_one_v2_draft() TO photo_maintenance;

-- Source: 00196_gateway_input.sql
-- Extend the existing fenced gateway capability to exact V2 closure rows.
-- +goose StatementBegin
CREATE OR REPLACE FUNCTION photo.gateway_input(p_task uuid,p_attempt integer,p_fence bigint,p_worker uuid,p_certificate text,p_artifact uuid)
RETURNS TABLE(artifact_id uuid,bucket text,object_key text,object_version text,sha256 text,bytes bigint,media_type text)
LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
 SELECT a.id,a.bucket,a.object_key,a.object_version,a.sha256,a.bytes,a.media_type
 FROM photo.authorize_gateway_task(p_task,p_attempt,p_fence,p_worker,p_certificate) permitted
 JOIN photo.tasks t ON t.tenant_id=permitted.tenant_id AND t.id=permitted.task_id
 JOIN photo.artifacts a ON a.tenant_id=t.tenant_id AND a.id=p_artifact
 WHERE a.state='ready' AND a.object_version IS NOT NULL AND a.object_version<>'' AND a.object_version<>'null'
 AND (a.expires_at IS NULL OR a.expires_at>clock_timestamp())
 AND (
  EXISTS (
   SELECT 1 FROM jsonb_array_elements(
    coalesce(t.dispatch_command->'inputs','[]'::jsonb) || jsonb_build_array(t.dispatch_command->'params')
   ) ref WHERE ref->>'artifact_id'=a.id::text AND ref->>'sha256'=a.sha256
  )
  OR (
   t.execution_profile->>'renderer_version'='v2.2'
   AND EXISTS(SELECT 1 FROM photo.operation_registry op WHERE op.operation=t.operation
    AND op.version=t.operation_version AND op.v2_enabled)
   AND EXISTS(SELECT 1 FROM photo.runs r JOIN photo.v2_workflows w
    ON w.tenant_id=r.tenant_id AND w.run_id=r.id AND w.renderer_version='v2.2'
    WHERE r.tenant_id=t.tenant_id AND r.id=t.run_id AND r.kind='v2'
    AND EXISTS(SELECT 1 FROM photo.v2_task_inputs i
     WHERE i.tenant_id=t.tenant_id AND i.task_id=t.id
      AND i.artifact_id=a.id AND i.sha256=a.sha256 AND i.project_id=w.project_id))
  )
 );
$$;
-- +goose StatementEnd
ALTER FUNCTION photo.gateway_input(uuid,integer,bigint,uuid,text,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.gateway_input(uuid,integer,bigint,uuid,text,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.gateway_input(uuid,integer,bigint,uuid,text,uuid) TO photo_gateway;

-- Source: 00196_output_protocol.sql
-- V2 output multiplicity; legacy limits and Apply reservation behavior remain unchanged.
ALTER TABLE photo.operation_output_policies DROP CONSTRAINT operation_output_policies_max_count_check;
ALTER TABLE photo.operation_output_policies ADD CONSTRAINT operation_output_policies_max_count_check CHECK(
 max_count BETWEEN 1 AND 128 OR
 (operation='session.plan' AND role='correction_plan' AND max_count BETWEEN 129 AND 5000) OR
 (operation IN('v2.interchange.import','v2.interchange.export') AND role='draft' AND max_count BETWEEN 129 AND 5000) OR
 (operation='v2.interchange.parse' AND role='imported_file' AND max_count BETWEEN 129 AND 30000));

-- +goose StatementBegin
CREATE OR REPLACE FUNCTION photo.begin_output(p_task uuid,p_attempt integer,p_fence bigint,p_worker uuid,p_certificate text,
 p_key uuid,p_role text,p_bytes bigint,p_sha text,p_media text,p_bucket text)
RETURNS TABLE(outcome text,upload_id uuid,artifact_id uuid,object_key text,sha256 text)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE t photo.tasks%ROWTYPE; policy photo.operation_output_policies%ROWTYPE; old photo.output_uploads%ROWTYPE;
 q photo.quota_reservations%ROWTYPE; uid uuid:=gen_random_uuid(); aid uuid:=gen_random_uuid(); target text;
 maximum numeric; used numeric; budget numeric; from_run boolean:=false; v2 boolean:=false;
 is_v2_run boolean:=false; max_total integer:=128;
BEGIN
 IF p_key IS NULL OR p_key='00000000-0000-0000-0000-000000000000'::uuid OR p_role IS NULL OR p_role !~ '^[a-z][a-z0-9_-]{0,63}$'
 OR p_bytes IS NULL OR p_bytes<0 OR p_bytes>9007199254740991 OR p_sha IS NULL OR p_sha !~ '^[0-9a-f]{64}$'
 OR p_media IS NULL OR p_media !~ '^[a-z0-9.+-]+/[a-z0-9.+-]+$' OR p_bucket IS NULL OR length(p_bucket) NOT BETWEEN 3 AND 63 THEN
 RAISE EXCEPTION 'INVALID_UPLOAD' USING ERRCODE='22023'; END IF;
 t:=photo.lock_task(p_task);
 SELECT r.kind='v2',r.kind='v2' AND t.execution_profile->>'renderer_version'='v2.2'
  AND EXISTS(SELECT 1 FROM photo.v2_workflows w WHERE w.tenant_id=r.tenant_id AND w.run_id=r.id AND w.renderer_version='v2.2')
  AND EXISTS(SELECT 1 FROM photo.operation_registry op WHERE op.operation=t.operation
   AND op.version=t.operation_version AND op.v2_enabled)
  INTO is_v2_run,v2 FROM photo.runs r WHERE r.tenant_id=t.tenant_id AND r.id=t.run_id;
 v2:=coalesce(v2,false);
 IF t.id IS NULL OR NOT EXISTS(SELECT FROM photo.authorize_gateway_task(p_task,p_attempt,p_fence,p_worker,p_certificate)) THEN
  RETURN QUERY SELECT 'stale',NULL::uuid,NULL::uuid,NULL::text,NULL::text; RETURN; END IF;
 IF is_v2_run AND NOT v2 THEN
  RETURN QUERY SELECT 'forbidden',NULL::uuid,NULL::uuid,NULL::text,NULL::text; RETURN; END IF;
 SELECT * INTO old FROM photo.output_uploads u WHERE u.tenant_id=t.tenant_id AND u.task_id=t.id AND u.attempt=p_attempt AND u.fence=p_fence AND u.idempotency_key=p_key FOR UPDATE;
 IF FOUND THEN
  IF old.worker_id<>p_worker OR old.certificate_sha256<>p_certificate OR old.role<>p_role OR old.bytes<>p_bytes OR old.sha256<>p_sha OR old.media_type<>p_media OR old.bucket<>p_bucket THEN
   RETURN QUERY SELECT 'conflict',NULL::uuid,NULL::uuid,NULL::text,NULL::text;
  ELSIF old.state='ready' THEN RETURN QUERY SELECT 'replayed',old.id,old.artifact_id,old.object_key,old.sha256;
  ELSE RETURN QUERY SELECT 'busy',NULL::uuid,NULL::uuid,NULL::text,NULL::text;
  END IF; RETURN;
 END IF;
 SELECT * INTO policy FROM photo.operation_output_policies p WHERE p.operation=t.operation AND p.version=t.operation_version AND p.role=p_role;
 IF NOT FOUND OR NOT(policy.media_types ? p_media) OR p_bytes>policy.max_bytes THEN
  RETURN QUERY SELECT 'forbidden',NULL::uuid,NULL::uuid,NULL::text,NULL::text; RETURN; END IF;
 IF v2 THEN
  SELECT least(coalesce(sum(max_count),0),30001)::integer INTO max_total FROM photo.operation_output_policies
   WHERE operation=t.operation AND version=t.operation_version;
 END IF;
 IF max_total<1 OR (SELECT count(*) FROM photo.output_uploads u WHERE u.task_id=t.id AND u.attempt=p_attempt AND u.fence=p_fence)>=max_total
 OR (SELECT count(*) FROM photo.output_uploads u WHERE u.task_id=t.id AND u.attempt=p_attempt AND u.fence=p_fence AND u.role=p_role)>=policy.max_count THEN
  RETURN QUERY SELECT 'quota',NULL::uuid,NULL::uuid,NULL::text,NULL::text; RETURN; END IF;
 IF v2 AND p_role='document' AND EXISTS(SELECT 1 FROM photo.output_uploads u
  WHERE u.task_id=t.id AND u.attempt=p_attempt AND u.fence=p_fence AND u.role<>'document' AND u.state<>'ready') THEN
  RETURN QUERY SELECT 'forbidden',NULL::uuid,NULL::uuid,NULL::text,NULL::text; RETURN;
 END IF;
 budget:=(t.execution_profile->'resource_estimate'->>'output_bytes')::numeric;
 SELECT coalesce(sum(u.bytes),0) INTO used FROM photo.output_uploads u WHERE u.task_id=t.id AND u.attempt=p_attempt AND u.fence=p_fence;
 IF budget IS NULL OR budget<0 OR used+p_bytes>budget THEN
  RETURN QUERY SELECT 'quota',NULL::uuid,NULL::uuid,NULL::text,NULL::text; RETURN; END IF;

 -- The row lock serializes all output allocations for the run. Only apply runs
 -- may spend a run reservation; every other task follows the common path.
 SELECT x.* INTO q FROM photo.quota_reservations x JOIN photo.runs r ON r.tenant_id=x.tenant_id AND r.id=x.holder_id
 WHERE x.tenant_id=t.tenant_id AND x.holder_type='run' AND x.holder_id=t.run_id AND x.state='reserved'
 AND (r.kind='apply' OR (v2 AND r.kind='v2')) AND x.expires_at>clock_timestamp() FOR UPDATE OF x;
 IF v2 AND (NOT FOUND OR q.bytes<p_bytes) THEN
  RETURN QUERY SELECT 'quota',NULL::uuid,NULL::uuid,NULL::text,NULL::text; RETURN;
 END IF;
 IF FOUND AND q.bytes>=p_bytes THEN
  UPDATE photo.quota_reservations SET bytes=bytes-p_bytes WHERE tenant_id=q.tenant_id AND id=q.id AND bytes>=p_bytes;
  IF NOT FOUND THEN RAISE EXCEPTION 'RUN_RESERVATION_INCONSISTENT' USING ERRCODE='23514'; END IF;
  from_run:=true;
 ELSE
  SELECT (quotas->>'storage_bytes')::numeric INTO maximum FROM photo.tenants WHERE id=t.tenant_id;
  SELECT storage_bytes::numeric+reserved_bytes INTO used FROM photo.tenant_usage WHERE tenant_id=t.tenant_id;
  IF maximum IS NULL OR used IS NULL OR used+p_bytes>maximum OR used+p_bytes>9007199254740991 THEN
   RETURN QUERY SELECT 'quota',NULL::uuid,NULL::uuid,NULL::text,NULL::text; RETURN; END IF;
 END IF;
 target:='tenants/'||t.tenant_id||'/tasks/'||t.id||'/attempts/'||p_attempt||'/fences/'||p_fence||'/'||aid;
 INSERT INTO photo.output_uploads(id,tenant_id,task_id,attempt,fence,worker_id,certificate_sha256,idempotency_key,artifact_id,role,bucket,object_key,sha256,bytes,media_type,run_reservation_id)
 VALUES(uid,t.tenant_id,t.id,p_attempt,p_fence,p_worker,p_certificate,p_key,aid,p_role,p_bucket,target,p_sha,p_bytes,p_media,CASE WHEN from_run THEN q.id END);
 IF NOT from_run THEN UPDATE photo.tenant_usage SET reserved_bytes=reserved_bytes+p_bytes WHERE tenant_id=t.tenant_id; END IF;
 RETURN QUERY SELECT 'created',uid,aid,target,p_sha;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.begin_output(uuid,integer,bigint,uuid,text,uuid,text,bigint,text,text,text) OWNER TO photo_fn_owner;

-- Source: 00196_worker_renderer_gate.sql
-- Old workers cannot lease a V2 task merely because they qualify for a legacy
-- operation name/backend. The empty default is intentionally fail-closed.
ALTER TABLE photo.worker_registrations ADD COLUMN v2_renderer_versions jsonb NOT NULL DEFAULT '[]'::jsonb
 CHECK (jsonb_typeof(v2_renderer_versions)='array');

-- +goose StatementBegin
CREATE OR REPLACE FUNCTION photo.reserve_dispatch(p_task uuid,p_node text,p_ram bigint,p_vram bigint,p_scratch bigint,p_event uuid,p_correlation uuid,p_trace text)
RETURNS TABLE(outcome text,command jsonb)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE reserved record; t photo.tasks%ROWTYPE; target uuid; run_kind text;
BEGIN
 SELECT * INTO reserved FROM photo.reserve_dispatch_resources(p_task,p_node,p_ram,p_vram,p_scratch,p_event,p_correlation,p_trace);
 IF reserved.outcome='queued' THEN
  SELECT * INTO t FROM photo.tasks WHERE id=p_task;
  SELECT r.kind INTO run_kind FROM photo.runs r WHERE r.tenant_id=t.tenant_id AND r.id=t.run_id;
  IF run_kind='v2' AND NOT photo.v2_input_closure_ready(p_task) THEN
   RAISE EXCEPTION 'V2_INPUT_CLOSURE_UNSEALED' USING ERRCODE='23514';
  END IF;
  SELECT w.worker_id INTO target FROM photo.worker_registrations w
  WHERE w.tenant_id=t.tenant_id AND w.node_id=p_node AND w.enabled AND w.db_principal IS NOT NULL
  AND w.resource_classes ? t.resource_class AND w.backends ? (t.execution_profile->>'backend')
  AND (w.qualified_operations->t.operation) ? (t.execution_profile->>'backend')
  AND w.last_seen>clock_timestamp()-interval '30 seconds'
  AND ((reserved.command->'model')='null'::jsonb OR w.lock_id=reserved.command->'model'->>'lock_id')
  AND (run_kind<>'v2' OR (t.execution_profile->>'renderer_version'='v2.2'
   AND EXISTS(SELECT 1 FROM photo.operation_registry op WHERE op.operation=t.operation
    AND op.version=t.operation_version AND op.v2_enabled)
   AND w.v2_renderer_versions ? 'v2.2'
   AND EXISTS(SELECT 1 FROM photo.v2_workflows wf WHERE wf.tenant_id=t.tenant_id
    AND wf.run_id=t.run_id AND wf.renderer_version='v2.2')))
  ORDER BY w.worker_id LIMIT 1 FOR SHARE;
  IF target IS NULL THEN RAISE EXCEPTION 'worker changed during admission' USING ERRCODE='40001'; END IF;
  UPDATE photo.tasks SET dispatch_worker_id=target WHERE id=t.id;
  UPDATE photo.outbox SET routing_key='worker.'||target||'.'||routing_key WHERE tenant_id=t.tenant_id AND event_id=p_event;
 END IF;
 RETURN QUERY SELECT reserved.outcome,reserved.command;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.reserve_dispatch(uuid,text,bigint,bigint,bigint,uuid,uuid,text) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.reserve_dispatch(uuid,text,bigint,bigint,bigint,uuid,uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.reserve_dispatch(uuid,text,bigint,bigint,bigint,uuid,uuid,text) TO photo_scheduler;

-- +goose StatementBegin
CREATE OR REPLACE FUNCTION photo.claim_task(p_task uuid,p_attempt integer,p_worker uuid,p_command jsonb)
RETURNS TABLE(outcome text,fence bigint,lease_until timestamptz,deadline timestamptz,context jsonb)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE t photo.tasks%ROWTYPE; run_kind text;
BEGIN
 t:=photo.lock_task(p_task);
 IF t.id IS NULL THEN
  RETURN QUERY SELECT 'stale',NULL::bigint,NULL::timestamptz,NULL::timestamptz,NULL::jsonb;RETURN;
 END IF;
 IF t.dispatch_worker_id IS NOT NULL AND t.dispatch_worker_id IS DISTINCT FROM p_worker THEN
  RETURN QUERY SELECT 'unauthorized',NULL::bigint,NULL::timestamptz,NULL::timestamptz,NULL::jsonb;RETURN;
 END IF;
 SELECT r.kind INTO run_kind FROM photo.runs r WHERE r.tenant_id=t.tenant_id AND r.id=t.run_id;
 IF run_kind='v2' AND (
   t.execution_profile->>'renderer_version' IS DISTINCT FROM 'v2.2'
   OR NOT photo.v2_input_closure_ready(p_task)
   OR NOT EXISTS(SELECT 1 FROM photo.operation_registry op WHERE op.operation=t.operation
    AND op.version=t.operation_version AND op.v2_enabled)
   OR NOT EXISTS(SELECT 1 FROM photo.v2_workflows w WHERE w.tenant_id=t.tenant_id
    AND w.run_id=t.run_id AND w.renderer_version='v2.2')
   OR NOT EXISTS(SELECT 1 FROM photo.worker_registrations w WHERE w.tenant_id=t.tenant_id
    AND w.worker_id=p_worker AND w.v2_renderer_versions ? 'v2.2')
  ) THEN
  RETURN QUERY SELECT 'unauthorized',NULL::bigint,NULL::timestamptz,NULL::timestamptz,NULL::jsonb;RETURN;
 END IF;
 RETURN QUERY SELECT * FROM photo.claim_task_reserved(p_task,p_attempt,p_worker,p_command);
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.claim_task(uuid,integer,uuid,jsonb) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.claim_task(uuid,integer,uuid,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.claim_task(uuid,integer,uuid,jsonb) TO photo_worker;

-- Source: 00196_result_root.sql
-- V2 success carries one root document. Nested uploads are adopted separately;
-- they must never be smuggled through the legacy TaskResult.outputs envelope.
-- +goose StatementBegin
CREATE FUNCTION photo.guard_v2_result_root() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE task_row photo.tasks%ROWTYPE; run_row photo.runs%ROWTYPE; root jsonb;
BEGIN
 SELECT * INTO task_row FROM photo.tasks WHERE tenant_id=NEW.tenant_id AND id=NEW.task_id;
 IF NOT FOUND THEN RETURN NEW; END IF;
 SELECT * INTO run_row FROM photo.runs WHERE tenant_id=task_row.tenant_id AND id=task_row.run_id;
 IF run_row.kind<>'v2' THEN RETURN NEW; END IF;
 IF task_row.execution_profile->>'renderer_version' IS DISTINCT FROM 'v2.2'
  OR NOT EXISTS(SELECT 1 FROM photo.v2_workflows w WHERE w.tenant_id=run_row.tenant_id
   AND w.run_id=run_row.id AND w.renderer_version='v2.2') THEN
  RAISE EXCEPTION 'V2_RENDERER_MISMATCH' USING ERRCODE='23514';
 END IF;
 IF jsonb_typeof(NEW.outputs)<>'array' OR jsonb_array_length(NEW.outputs)<>1 THEN
  RAISE EXCEPTION 'V2_ROOT_REQUIRED' USING ERRCODE='23514';
 END IF;
 root:=NEW.outputs->0;
 IF jsonb_typeof(root)<>'object' OR (root-'artifact_id'-'sha256')<>'{}'::jsonb
  OR root->>'artifact_id' IS NULL OR root->>'sha256' IS NULL
  OR NOT EXISTS(SELECT 1 FROM photo.artifacts a
   JOIN photo.output_uploads u ON u.tenant_id=a.tenant_id AND u.artifact_id=a.id
   WHERE a.tenant_id=NEW.tenant_id AND a.id=(root->>'artifact_id')::uuid
   AND a.sha256=root->>'sha256' AND a.output_role='document' AND a.state='ready'
   AND a.verified_at IS NOT NULL AND a.object_version IS NOT NULL
   AND a.created_by_task_id=task_row.id AND a.produced_attempt=NEW.attempt
   AND a.produced_fence=NEW.fencing_token AND u.state='ready' AND u.role='document'
   AND u.task_id=task_row.id AND u.attempt=NEW.attempt AND u.fence=NEW.fencing_token) THEN
  RAISE EXCEPTION 'V2_ROOT_UNVERIFIED' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.guard_v2_result_root() OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.guard_v2_result_root() FROM PUBLIC;
CREATE TRIGGER v2_result_root_guard BEFORE INSERT ON photo.task_results
 FOR EACH ROW EXECUTE FUNCTION photo.guard_v2_result_root();

-- Source: 00196_adoption.sql
-- The service validates typed JSON closure bytes before this transaction.
-- This boundary rechecks every relational fact and publishes no partial result.
-- +goose StatementBegin
CREATE FUNCTION photo.v2_adoption_event_id(p_task uuid,p_result uuid) RETURNS uuid
LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE h bytea;
BEGIN
 h:=public.digest(uuid_send(p_task)||convert_to('adopt:'||p_result::text,'UTF8'),'sha1');
 h:=set_byte(h,6,(get_byte(h,6)&15)|80);
 h:=set_byte(h,8,(get_byte(h,8)&63)|128);
 RETURN encode(substring(h FROM 1 FOR 16),'hex')::uuid;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.v2_adoption_event_id(uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.v2_adoption_event_id(uuid,uuid) FROM PUBLIC;

-- Inventory rows are {artifact_id,sha256,purpose,ordinal}; ordinal 0 is the
-- root. All newly produced members must have the same exact upload fence.
-- A service call uses the digest of its validated canonical inventory.
-- +goose StatementBegin
CREATE FUNCTION photo.adopt_v2_plan(p_tenant uuid,p_task uuid,p_attempt integer,p_fence bigint,
 p_result uuid,p_inventory jsonb,p_digest text) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE tenant_row photo.tenants%ROWTYPE;run_row photo.runs%ROWTYPE;task_row photo.tasks%ROWTYPE;
 result_row photo.task_results%ROWTYPE;workflow_row photo.v2_workflows%ROWTYPE;
 artifact_row photo.artifacts%ROWTYPE;upload_row photo.output_uploads%ROWTYPE;
 ref record; root jsonb; marker uuid; prior jsonb; sql_digest text; next_cursor bigint;
BEGIN
 IF p_digest IS NULL OR p_digest !~ '^[0-9a-f]{64}$' OR p_inventory IS NULL
  OR jsonb_typeof(p_inventory)<>'array' OR jsonb_array_length(p_inventory) NOT BETWEEN 1 AND 30001
  OR pg_column_size(p_inventory)>16777216 THEN
  RAISE EXCEPTION 'V2_ADOPTION_INVENTORY_INVALID' USING ERRCODE='22023';
 END IF;
 sql_digest:=encode(sha256(convert_to(p_inventory::text,'UTF8')),'hex');
 SELECT * INTO tenant_row FROM photo.tenants WHERE id=p_tenant FOR UPDATE;
 IF tenant_row.id IS NULL OR tenant_row.status<>'active' THEN RETURN false;END IF;
 SELECT * INTO task_row FROM photo.tasks WHERE tenant_id=p_tenant AND id=p_task;
 IF task_row.id IS NULL THEN RETURN false;END IF;
 SELECT * INTO run_row FROM photo.runs WHERE tenant_id=p_tenant AND id=task_row.run_id FOR UPDATE;
 SELECT * INTO task_row FROM photo.tasks WHERE tenant_id=p_tenant AND id=p_task FOR UPDATE;
 IF run_row.id IS NULL OR run_row.kind<>'v2' OR task_row.run_id<>run_row.id
  OR task_row.canonical_result_id IS DISTINCT FROM p_result OR task_row.attempt IS DISTINCT FROM p_attempt
  OR task_row.fencing_token IS DISTINCT FROM p_fence THEN RETURN false;END IF;
 marker:=photo.v2_adoption_event_id(p_task,p_result);
 SELECT e.payload INTO prior FROM photo.inbox i JOIN photo.run_events e
  ON e.tenant_id=i.tenant_id AND e.run_id=run_row.id AND e.type='v2.task.adopted'
  AND e.payload->>'task_id'=p_task::text AND e.payload->>'result_id'=p_result::text
  WHERE i.tenant_id=p_tenant AND i.consumer='v2-adopt' AND i.event_id=marker;
 IF EXISTS(SELECT 1 FROM photo.inbox i WHERE i.tenant_id=p_tenant AND i.consumer='v2-adopt' AND i.event_id=marker) THEN
  IF prior->>'inventory_digest'=p_digest AND prior->>'sql_digest'=sql_digest THEN RETURN false;END IF;
  RAISE EXCEPTION 'V2_ADOPTION_RESULT_CONFLICT' USING ERRCODE='23514';
 END IF;
 IF run_row.status<>'running' OR run_row.cancel_requested OR task_row.cancel_requested
  OR task_row.state<>'succeeded' OR task_row.execution_profile->>'renderer_version' IS DISTINCT FROM 'v2.2' THEN
  RETURN false;
 END IF;
 SELECT * INTO workflow_row FROM photo.v2_workflows w WHERE w.tenant_id=p_tenant
  AND w.run_id=run_row.id AND w.renderer_version='v2.2';
 IF workflow_row.id IS NULL THEN RETURN false;END IF;
 SELECT * INTO result_row FROM photo.task_results z WHERE z.tenant_id=p_tenant
  AND z.id=p_result AND z.task_id=p_task AND z.attempt=p_attempt AND z.fencing_token=p_fence;
 IF result_row.id IS NULL OR jsonb_typeof(result_row.outputs)<>'array'
  OR jsonb_array_length(result_row.outputs)<>1 THEN RETURN false;END IF;
 root:=result_row.outputs->0;
 IF p_inventory->0->>'artifact_id' IS DISTINCT FROM root->>'artifact_id'
  OR p_inventory->0->>'sha256' IS DISTINCT FROM root->>'sha256' THEN
  RAISE EXCEPTION 'V2_ADOPTION_ROOT_MISMATCH' USING ERRCODE='23514';
 END IF;
 IF EXISTS(
  WITH entries AS MATERIALIZED (
   SELECT (value->>'artifact_id')::uuid AS artifact_id FROM jsonb_array_elements(p_inventory)
    WHERE coalesce(value->>'artifact_id','') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  )
  SELECT 1 FROM photo.output_uploads u LEFT JOIN entries e ON e.artifact_id=u.artifact_id
   WHERE u.tenant_id=p_tenant AND u.task_id=p_task AND u.attempt=p_attempt AND u.fence=p_fence
    AND (u.state<>'ready' OR e.artifact_id IS NULL)
 ) THEN RAISE EXCEPTION 'V2_ADOPTION_OUTPUT_INCOMPLETE' USING ERRCODE='23514';END IF;
 FOR ref IN SELECT value,ordinality-1 AS ordinal FROM jsonb_array_elements(p_inventory) WITH ORDINALITY LOOP
  IF jsonb_typeof(ref.value)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(ref.value))<>4
   OR NOT (ref.value ?& ARRAY['artifact_id','sha256','purpose','ordinal'])
   OR coalesce(ref.value->>'artifact_id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   OR coalesce(ref.value->>'sha256','') !~ '^[0-9a-f]{64}$'
   OR coalesce(ref.value->>'purpose','') !~ '^[0-9a-f]{64}$'
   OR ref.value->>'ordinal' IS DISTINCT FROM ref.ordinal::text THEN
   RAISE EXCEPTION 'V2_ADOPTION_INVENTORY_INVALID' USING ERRCODE='22023';
  END IF;
  SELECT * INTO artifact_row FROM photo.artifacts a WHERE a.tenant_id=p_tenant
   AND a.id=(ref.value->>'artifact_id')::uuid FOR SHARE;
  IF artifact_row.id IS NULL OR artifact_row.sha256<>ref.value->>'sha256'
   OR artifact_row.state<>'ready' OR artifact_row.verified_at IS NULL
   OR artifact_row.object_version IS NULL OR artifact_row.object_version IN ('','null')
   OR (artifact_row.expires_at IS NOT NULL AND artifact_row.expires_at<=clock_timestamp()) THEN
   RAISE EXCEPTION 'V2_ADOPTION_ARTIFACT_UNVERIFIED' USING ERRCODE='23514';
  END IF;
  IF artifact_row.created_by_task_id=p_task AND artifact_row.produced_attempt=p_attempt
   AND artifact_row.produced_fence=p_fence THEN
   SELECT * INTO upload_row FROM photo.output_uploads u WHERE u.tenant_id=p_tenant
    AND u.artifact_id=artifact_row.id AND u.task_id=p_task AND u.attempt=p_attempt
    AND u.fence=p_fence AND u.state='ready' AND u.sha256=artifact_row.sha256
    AND u.role=artifact_row.output_role FOR SHARE;
   IF upload_row.id IS NULL THEN
    RAISE EXCEPTION 'V2_ADOPTION_UPLOAD_UNVERIFIED' USING ERRCODE='23514';
   END IF;
  ELSIF NOT EXISTS(SELECT 1 FROM photo.v2_task_inputs i WHERE i.tenant_id=p_tenant
   AND i.project_id=workflow_row.project_id AND i.task_id=p_task
   AND i.artifact_id=artifact_row.id AND i.sha256=artifact_row.sha256) THEN
   RAISE EXCEPTION 'V2_ADOPTION_UNDECLARED_INPUT' USING ERRCODE='23514';
  END IF;
  INSERT INTO photo.v2_artifact_links(tenant_id,project_id,workflow_id,artifact_id,sha256,purpose,ordinal)
   VALUES(p_tenant,workflow_row.project_id,workflow_row.id,artifact_row.id,
    artifact_row.sha256,ref.value->>'purpose',ref.ordinal);
 END LOOP;
 INSERT INTO photo.inbox(tenant_id,consumer,event_id,processed_at)
  VALUES(p_tenant,'v2-adopt',marker,clock_timestamp());
 INSERT INTO photo.tenant_event_cursors(tenant_id,last_cursor) VALUES(p_tenant,0)
  ON CONFLICT(tenant_id) DO NOTHING;
 UPDATE photo.tenant_event_cursors SET last_cursor=last_cursor+1
  WHERE tenant_id=p_tenant AND last_cursor<9007199254740991 RETURNING last_cursor INTO next_cursor;
 IF next_cursor IS NULL THEN RAISE EXCEPTION 'EVENT_CURSOR_EXHAUSTED' USING ERRCODE='23514';END IF;
 INSERT INTO photo.run_events(tenant_id,cursor,run_id,principal_id,audience,type,payload)
  VALUES(p_tenant,next_cursor,run_row.id,run_row.created_by,'principal','v2.task.adopted',
   jsonb_build_object('task_id',p_task,'result_id',p_result,'attempt',p_attempt,'fence',p_fence,
    'inventory_digest',p_digest,'sql_digest',sql_digest,'inventory_count',jsonb_array_length(p_inventory)));
 INSERT INTO photo.outbox(tenant_id,event_id,destination,routing_key,payload)
  VALUES(p_tenant,marker,'photo.events.v1','v2.task.adopted',
   jsonb_build_object('schema_version',1,'event_id',marker,'type','v2.task.adopted',
    'tenant_id',p_tenant,'run_id',run_row.id,'task_id',p_task,'result_id',p_result));
 RETURN true;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.adopt_v2_plan(uuid,uuid,integer,bigint,uuid,jsonb,text) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.adopt_v2_plan(uuid,uuid,integer,bigint,uuid,jsonb,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.adopt_v2_plan(uuid,uuid,integer,bigint,uuid,jsonb,text) TO photo_scheduler;

-- A semantic validation failure stops new work but lets existing leases be
-- fenced by the normal cancellation path. The finalizer reports failed once
-- every task is terminal; this event distinguishes it from a user cancel.
-- +goose StatementBegin
CREATE FUNCTION photo.reject_v2_adoption(p_tenant uuid,p_task uuid,p_result uuid,p_code text)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE tenant_row photo.tenants%ROWTYPE;r photo.runs%ROWTYPE;t photo.tasks%ROWTYPE;
 next_cursor bigint;ev uuid:=gen_random_uuid();
BEGIN
 IF p_code IS NULL OR p_code !~ '^[A-Z][A-Z0-9_]{0,79}$' THEN
  RAISE EXCEPTION 'V2_ADOPTION_FAILURE_CODE_INVALID' USING ERRCODE='22023';
 END IF;
 SELECT * INTO tenant_row FROM photo.tenants WHERE id=p_tenant FOR UPDATE;
 IF tenant_row.id IS NULL OR tenant_row.status<>'active' THEN RETURN false;END IF;
 SELECT * INTO t FROM photo.tasks WHERE tenant_id=p_tenant AND id=p_task;
 IF t.id IS NULL THEN RETURN false;END IF;
 SELECT * INTO r FROM photo.runs WHERE tenant_id=p_tenant AND id=t.run_id FOR UPDATE;
 SELECT * INTO t FROM photo.tasks WHERE tenant_id=p_tenant AND id=p_task FOR UPDATE;
 IF r.id IS NULL OR r.kind<>'v2' OR r.status<>'running' OR r.cancel_requested
  OR t.state<>'succeeded' OR t.canonical_result_id IS DISTINCT FROM p_result
  OR EXISTS(SELECT 1 FROM photo.inbox i WHERE i.tenant_id=p_tenant AND i.consumer='v2-adopt'
   AND i.event_id=photo.v2_adoption_event_id(p_task,p_result)) THEN RETURN false;END IF;
 IF r.revision>=9007199254740991 THEN RAISE EXCEPTION 'REVISION_EXHAUSTED' USING ERRCODE='23514';END IF;
 UPDATE photo.runs SET cancel_requested=true,status='cancelling',revision=revision+1
  WHERE tenant_id=p_tenant AND id=r.id;
 INSERT INTO photo.tenant_event_cursors(tenant_id,last_cursor) VALUES(p_tenant,0)
  ON CONFLICT(tenant_id) DO NOTHING;
 UPDATE photo.tenant_event_cursors SET last_cursor=last_cursor+1
  WHERE tenant_id=p_tenant AND last_cursor<9007199254740991 RETURNING last_cursor INTO next_cursor;
 IF next_cursor IS NULL THEN RAISE EXCEPTION 'EVENT_CURSOR_EXHAUSTED' USING ERRCODE='23514';END IF;
 INSERT INTO photo.run_events(tenant_id,cursor,run_id,principal_id,audience,type,payload)
  VALUES(p_tenant,next_cursor,r.id,r.created_by,'principal','v2.adoption.failed',
   jsonb_build_object('task_id',p_task,'result_id',p_result,'code',p_code));
 INSERT INTO photo.outbox(tenant_id,event_id,destination,routing_key,payload)
  VALUES(p_tenant,ev,'photo.events.v1','v2.adoption.failed',
   jsonb_build_object('schema_version',1,'event_id',ev,'type','v2.adoption.failed',
    'tenant_id',p_tenant,'run_id',r.id,'task_id',p_task,'code',p_code));
 RETURN true;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.reject_v2_adoption(uuid,uuid,uuid,text) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.reject_v2_adoption(uuid,uuid,uuid,text) FROM PUBLIC;
