-- Source: 00196_adoption_reads.sql
-- Read-only evidence for the trusted adopter. The object-store location is
-- returned only for an exact V2 task input or its own verified output.
-- +goose StatementBegin
CREATE FUNCTION photo.v2_adoption_artifact(p_tenant uuid,p_task uuid,p_attempt integer,p_fence bigint,p_artifact uuid)
RETURNS TABLE(bucket text,object_key text,object_version text,sha256 text,bytes bigint,
 media_type text,role text,source text)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
 SELECT a.bucket,a.object_key,a.object_version,a.sha256,a.bytes,a.media_type,
  CASE WHEN u.id IS NOT NULL THEN u.role ELSE NULL END,
  CASE WHEN u.id IS NOT NULL THEN 'output' ELSE 'input' END
 FROM photo.tasks t JOIN photo.runs r ON r.tenant_id=t.tenant_id AND r.id=t.run_id
 JOIN photo.v2_workflows w ON w.tenant_id=r.tenant_id AND w.run_id=r.id
 JOIN photo.tenants tenant ON tenant.id=r.tenant_id
 JOIN photo.artifacts a ON a.tenant_id=t.tenant_id AND a.id=p_artifact
 LEFT JOIN photo.output_uploads u ON u.tenant_id=t.tenant_id AND u.artifact_id=a.id
  AND u.task_id=t.id AND u.attempt=p_attempt AND u.fence=p_fence AND u.state='ready'
 LEFT JOIN photo.v2_task_inputs i ON i.tenant_id=t.tenant_id AND i.project_id=w.project_id
  AND i.task_id=t.id AND i.artifact_id=a.id AND i.sha256=a.sha256
 WHERE t.tenant_id=p_tenant AND t.id=p_task AND t.attempt=p_attempt AND t.fencing_token=p_fence
 AND t.state='succeeded' AND t.canonical_result_id IS NOT NULL AND NOT t.cancel_requested
 AND r.kind='v2' AND r.status='running' AND NOT r.cancel_requested AND tenant.status='active'
 AND w.renderer_version='v2.2' AND t.execution_profile->>'renderer_version'='v2.2'
 AND a.state='ready' AND a.verified_at IS NOT NULL
 AND a.object_version IS NOT NULL AND a.object_version NOT IN ('','null')
 AND (a.expires_at IS NULL OR a.expires_at>clock_timestamp())
 AND (u.id IS NOT NULL OR i.id IS NOT NULL)
 AND (u.id IS NULL OR (a.created_by_task_id=t.id AND a.produced_attempt=p_attempt
  AND a.produced_fence=p_fence AND a.sha256=u.sha256 AND a.output_role=u.role));
$$;
-- +goose StatementEnd
ALTER FUNCTION photo.v2_adoption_artifact(uuid,uuid,integer,bigint,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.v2_adoption_artifact(uuid,uuid,integer,bigint,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.v2_adoption_artifact(uuid,uuid,integer,bigint,uuid) TO photo_scheduler;

-- +goose StatementBegin
CREATE FUNCTION photo.v2_adoption_staged_outputs(p_tenant uuid,p_task uuid,p_attempt integer,p_fence bigint)
RETURNS TABLE(artifact_id uuid,sha256 text,state text)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
 SELECT u.artifact_id,u.sha256,u.state FROM photo.output_uploads u
 JOIN photo.tasks t ON t.tenant_id=u.tenant_id AND t.id=u.task_id
 JOIN photo.runs r ON r.tenant_id=t.tenant_id AND r.id=t.run_id
 JOIN photo.v2_workflows w ON w.tenant_id=r.tenant_id AND w.run_id=r.id
 JOIN photo.tenants tenant ON tenant.id=r.tenant_id
 WHERE u.tenant_id=p_tenant AND u.task_id=p_task AND u.attempt=p_attempt AND u.fence=p_fence
 AND t.attempt=p_attempt AND t.fencing_token=p_fence AND t.state='succeeded'
 AND NOT t.cancel_requested AND r.kind='v2' AND r.status='running' AND NOT r.cancel_requested
 AND tenant.status='active' AND w.renderer_version='v2.2'
 AND t.execution_profile->>'renderer_version'='v2.2';
$$;
-- +goose StatementEnd
ALTER FUNCTION photo.v2_adoption_staged_outputs(uuid,uuid,integer,bigint) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.v2_adoption_staged_outputs(uuid,uuid,integer,bigint) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.v2_adoption_staged_outputs(uuid,uuid,integer,bigint) TO photo_scheduler;

-- +goose StatementBegin
CREATE FUNCTION photo.v2_adoption_context(p_tenant uuid,p_task uuid)
RETURNS TABLE(attempt integer,fence bigint,result_id uuid,operation text,operation_version text,
 root_artifact_id uuid,root_sha256 text)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
 SELECT t.attempt,t.fencing_token,z.id,t.operation,t.operation_version,
  (z.outputs->0->>'artifact_id')::uuid,z.outputs->0->>'sha256'
 FROM photo.tasks t JOIN photo.runs r ON r.tenant_id=t.tenant_id AND r.id=t.run_id
 JOIN photo.v2_workflows w ON w.tenant_id=r.tenant_id AND w.run_id=r.id
 JOIN photo.task_results z ON z.tenant_id=t.tenant_id AND z.id=t.canonical_result_id AND z.task_id=t.id
 JOIN photo.tenants tenant ON tenant.id=r.tenant_id
 WHERE t.tenant_id=p_tenant AND t.id=p_task AND t.state='succeeded'
 AND r.kind='v2' AND r.status='running' AND NOT r.cancel_requested AND NOT t.cancel_requested
 AND tenant.status='active' AND w.renderer_version='v2.2'
 AND t.execution_profile->>'renderer_version'='v2.2'
 AND jsonb_typeof(z.outputs)='array' AND jsonb_array_length(z.outputs)=1
 AND z.attempt=t.attempt AND z.fencing_token=t.fencing_token;
$$;
-- +goose StatementEnd
ALTER FUNCTION photo.v2_adoption_context(uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.v2_adoption_context(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.v2_adoption_context(uuid,uuid) TO photo_scheduler;

-- +goose StatementBegin
CREATE FUNCTION photo.v2_pending_adoptions() RETURNS TABLE(tenant_id uuid,run_id uuid,task_id uuid)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
 SELECT t.tenant_id,t.run_id,t.id FROM photo.tasks t
 JOIN photo.runs r ON r.tenant_id=t.tenant_id AND r.id=t.run_id
 JOIN photo.v2_workflows w ON w.tenant_id=r.tenant_id AND w.run_id=r.id
 JOIN photo.tenants tenant ON tenant.id=r.tenant_id
 WHERE r.kind='v2' AND r.status='running' AND r.graph_sealed AND NOT r.cancel_requested
 AND tenant.status='active' AND t.state='succeeded' AND NOT t.cancel_requested
 AND t.canonical_result_id IS NOT NULL AND t.execution_profile->>'renderer_version'='v2.2'
 AND w.renderer_version='v2.2'
 AND NOT EXISTS(SELECT 1 FROM photo.inbox i WHERE i.tenant_id=t.tenant_id
  AND i.consumer='v2-adopt' AND i.event_id=photo.v2_adoption_event_id(t.id,t.canonical_result_id))
 ORDER BY t.created_at,t.id LIMIT 64;
$$;
-- +goose StatementEnd
ALTER FUNCTION photo.v2_pending_adoptions() OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.v2_pending_adoptions() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.v2_pending_adoptions() TO photo_scheduler;

-- +goose StatementBegin
CREATE FUNCTION photo.v2_pending_finalizations() RETURNS TABLE(tenant_id uuid,run_id uuid)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
 SELECT r.tenant_id,r.id FROM photo.runs r JOIN photo.tenants tenant ON tenant.id=r.tenant_id
 WHERE r.kind='v2' AND r.status IN ('running','cancelling') AND r.graph_sealed
 AND tenant.status='active'
 AND EXISTS(SELECT 1 FROM photo.tasks t WHERE t.tenant_id=r.tenant_id AND t.run_id=r.id)
 AND NOT EXISTS(SELECT 1 FROM photo.tasks t WHERE t.tenant_id=r.tenant_id AND t.run_id=r.id
  AND t.state NOT IN ('succeeded','failed','cancelled','skipped'))
 AND (r.cancel_requested OR r.status='cancelling' OR NOT EXISTS(
  SELECT 1 FROM photo.graph_expansions e WHERE e.tenant_id=r.tenant_id
   AND e.run_id=r.id AND e.state<>'closed'))
 AND (r.cancel_requested OR r.status='cancelling'
  OR EXISTS(SELECT 1 FROM photo.tasks t WHERE t.tenant_id=r.tenant_id AND t.run_id=r.id
   AND t.state IN ('failed','cancelled','skipped'))
  OR NOT EXISTS(SELECT 1 FROM photo.tasks t WHERE t.tenant_id=r.tenant_id AND t.run_id=r.id
   AND (t.state<>'succeeded' OR t.canonical_result_id IS NULL
    OR NOT EXISTS(SELECT 1 FROM photo.inbox i WHERE i.tenant_id=t.tenant_id
     AND i.consumer='v2-adopt' AND i.event_id=photo.v2_adoption_event_id(t.id,t.canonical_result_id)))))
 ORDER BY r.created_at,r.id LIMIT 64;
$$;
-- +goose StatementEnd
ALTER FUNCTION photo.v2_pending_finalizations() OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.v2_pending_finalizations() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.v2_pending_finalizations() TO photo_scheduler;

-- Source: 00196_finalize.sql
-- A canonical result is not publishable until its deterministic adoption
-- marker exists. One run is finalized per transaction after all tasks settle.
-- +goose StatementBegin
CREATE FUNCTION photo.finalize_v2_run(p_tenant uuid,p_run uuid) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE tenant_row photo.tenants%ROWTYPE;r photo.runs%ROWTYPE;q photo.quota_reservations%ROWTYPE;
 next_state text;next_cursor bigint;ev uuid;has_review boolean;
BEGIN
 SELECT * INTO tenant_row FROM photo.tenants WHERE id=p_tenant FOR UPDATE;
 IF tenant_row.id IS NULL OR tenant_row.status<>'active' THEN RETURN 'stale';END IF;
 SELECT * INTO r FROM photo.runs WHERE tenant_id=p_tenant AND id=p_run FOR UPDATE;
 IF r.id IS NULL OR r.kind<>'v2' THEN RETURN 'stale';END IF;
 IF r.status IN ('completed','failed','cancelled','waiting_review') THEN RETURN r.status;END IF;
 IF r.status NOT IN ('queued','running','cancelling') OR NOT r.graph_sealed THEN RETURN 'pending';END IF;
 IF EXISTS(SELECT 1 FROM photo.tasks t WHERE t.tenant_id=p_tenant AND t.run_id=p_run
  AND t.state NOT IN ('succeeded','failed','cancelled','skipped')) THEN RETURN 'pending';END IF;
 IF NOT EXISTS(SELECT 1 FROM photo.tasks t WHERE t.tenant_id=p_tenant AND t.run_id=p_run) THEN RETURN 'pending';END IF;
 IF r.cancel_requested OR r.status='cancelling' THEN
  UPDATE photo.graph_expansions SET state='closed',expansion_token=NULL,expansion_lease_until=NULL
   WHERE tenant_id=p_tenant AND run_id=p_run AND state<>'closed';
 ELSIF EXISTS(SELECT 1 FROM photo.graph_expansions e WHERE e.tenant_id=p_tenant
  AND e.run_id=p_run AND e.state<>'closed') THEN RETURN 'pending';END IF;
 IF r.cancel_requested OR r.status='cancelling' THEN
  next_state:=CASE WHEN EXISTS(SELECT 1 FROM photo.run_events e WHERE e.tenant_id=p_tenant
   AND e.run_id=p_run AND e.type='v2.adoption.failed') THEN 'failed' ELSE 'cancelled' END;
 ELSIF EXISTS(SELECT 1 FROM photo.tasks t WHERE t.tenant_id=p_tenant AND t.run_id=p_run
  AND t.state IN ('failed','cancelled','skipped')) THEN
  next_state:='failed';
 ELSE
  IF r.status<>'running' OR EXISTS(SELECT 1 FROM photo.tasks t
   WHERE t.tenant_id=p_tenant AND t.run_id=p_run AND (t.state<>'succeeded'
    OR t.canonical_result_id IS NULL
    OR NOT EXISTS(SELECT 1 FROM photo.inbox i WHERE i.tenant_id=p_tenant
     AND i.consumer='v2-adopt'
     AND i.event_id=photo.v2_adoption_event_id(t.id,t.canonical_result_id)))) THEN
   RETURN 'pending';
  END IF;
  SELECT EXISTS(SELECT 1 FROM photo.tasks t JOIN photo.task_results z
   ON z.tenant_id=t.tenant_id AND z.task_id=t.id AND z.id=t.canonical_result_id
   WHERE t.tenant_id=p_tenant AND t.run_id=p_run AND z.review_required) INTO has_review;
  next_state:=CASE WHEN has_review THEN 'waiting_review' ELSE 'completed' END;
 END IF;
 SELECT * INTO q FROM photo.quota_reservations x WHERE x.tenant_id=p_tenant
  AND x.holder_type='run' AND x.holder_id=p_run AND x.state='reserved' FOR UPDATE;
 IF q.id IS NOT NULL THEN
  UPDATE photo.tenant_usage SET reserved_bytes=reserved_bytes-q.bytes
   WHERE tenant_id=p_tenant AND reserved_bytes>=q.bytes;
  IF NOT FOUND THEN RAISE EXCEPTION 'V2_RESERVATION_INCONSISTENT' USING ERRCODE='23514';END IF;
  UPDATE photo.quota_reservations SET bytes=0,
   state=CASE WHEN next_state IN ('failed','cancelled') THEN 'released' ELSE 'consumed' END
   WHERE tenant_id=p_tenant AND id=q.id;
 END IF;
 IF r.revision>=9007199254740991 THEN RAISE EXCEPTION 'REVISION_EXHAUSTED' USING ERRCODE='23514';END IF;
 UPDATE photo.runs SET status=next_state,revision=revision+1 WHERE tenant_id=p_tenant AND id=p_run;
 INSERT INTO photo.tenant_event_cursors(tenant_id,last_cursor) VALUES(p_tenant,0)
  ON CONFLICT(tenant_id) DO NOTHING;
 UPDATE photo.tenant_event_cursors SET last_cursor=last_cursor+1
  WHERE tenant_id=p_tenant AND last_cursor<9007199254740991 RETURNING last_cursor INTO next_cursor;
 IF next_cursor IS NULL THEN RAISE EXCEPTION 'EVENT_CURSOR_EXHAUSTED' USING ERRCODE='23514';END IF;
 ev:=p_run;
 INSERT INTO photo.run_events(tenant_id,cursor,run_id,principal_id,audience,type,payload)
  VALUES(p_tenant,next_cursor,p_run,r.created_by,'principal','v2.run.'||next_state,
   jsonb_build_object('run_id',p_run,'status',next_state));
 INSERT INTO photo.outbox(tenant_id,event_id,destination,routing_key,payload)
  VALUES(p_tenant,ev,'photo.events.v1','v2.run.'||next_state,
   jsonb_build_object('schema_version',1,'event_id',ev,'type','v2.run.'||next_state,
    'tenant_id',p_tenant,'run_id',p_run,'status',next_state));
 RETURN next_state;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.finalize_v2_run(uuid,uuid) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.finalize_v2_run(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.finalize_v2_run(uuid,uuid) TO photo_scheduler;

-- Source: 00196_purge.sql
-- Extend the existing closed tenant purge allowlist after object cleanup proof.
-- +goose StatementBegin
CREATE OR REPLACE FUNCTION photo.finish_tenant_deletion(p_job uuid,p_token uuid) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE j photo.deletion_jobs%ROWTYPE;t text;
 tables_to_purge constant text[]:=ARRAY[
  'v2_document_approvals','v2_document_refs','v2_task_inputs','v2_review_batches','v2_artifact_links','model_qualifications','v2_documents','v2_document_streams','v2_workflows','v2_draft_uploads',
  'apply_v4_stages','apply_nodes','apply_builds','artifact_leases','asset_embeddings','asset_version_sources','bulk_item_results','collection_items',
  'dead_letters','defect_branches','derivatives','download_archive_plans','download_export_plans','download_intents','download_job_items','download_volumes','editor_drafts','export_batch_children','graph_expansions','ingest_catalog_items','ingest_decode_items','ingest_node_plans','ingest_originals','ingest_progress','ingest_rejections','interactive_tasks','media_retry_nodes','output_uploads','project_acl','publications','resource_reservations','resource_slots','result_cache','reviews','run_events','sections','share_sessions','snapshot_items','staging_cleanup','style_analysis_nodes','style_asset_bindings','style_candidates','style_import_builds','task_attempts','task_edges','task_results','training_pairs','upload_abort_cleanup','upload_parts','asset_versions','assets','backend_documents','bulk_operations','collections','download_build_state','download_jobs','export_batches','exports','ingest_upload_bindings','legacy_imports','media_retry_jobs','overrides','quota_reservations','share_links','snapshots','style_analysis_builds','style_versions','tasks','training_sets','upload_sessions','tenant_static_resources','artifacts','runs','styles','projects','export_presets','idempotency_records','inbox','invitations','outbox','scheduler_tenants','tenant_event_cursors','tenant_usage','worker_registrations'
 ];
BEGIN
 SELECT * INTO j FROM photo.deletion_jobs WHERE id=p_job AND resource_type='tenant' AND status='running' AND cleanup_token=p_token AND cleanup_lease_until>clock_timestamp() FOR UPDATE;
 IF NOT FOUND OR NOT EXISTS(SELECT FROM photo.tenants x WHERE x.id=j.tenant_id AND x.status='deleting') OR EXISTS(SELECT FROM photo.runs r WHERE r.tenant_id=j.tenant_id AND r.status IN('draft','queued','running','waiting_review','cancelling')) THEN RETURN false;END IF;
 SET CONSTRAINTS ALL DEFERRED;
 UPDATE photo.v2_document_streams SET current_document_id=NULL,approved_document_id=NULL WHERE tenant_id=j.tenant_id;
 FOREACH t IN ARRAY tables_to_purge LOOP EXECUTE format('DELETE FROM photo.%I WHERE tenant_id=$1',t) USING j.tenant_id;END LOOP;
 DELETE FROM photo.audit_log WHERE tenant_id=j.tenant_id AND action NOT LIKE 'tenant.%';UPDATE photo.memberships SET status='suspended',revision=revision+1 WHERE tenant_id=j.tenant_id AND status<>'suspended';
 INSERT INTO photo.audit_log(tenant_id,actor_type,actor_id,action,resource_type,resource_id,request_id,details) VALUES(j.tenant_id,'system',NULL,'tenant.deleted','tenant',j.tenant_id,gen_random_uuid(),jsonb_build_object('job_id',j.id,'cleanup_passes',j.cleanup_passes+1));
 UPDATE photo.tenants SET status='deleted',revision=revision+1 WHERE id=j.tenant_id AND status='deleting';UPDATE photo.deletion_jobs SET status='completed',cleanup_token=NULL,cleanup_lease_until=NULL,cleanup_passes=cleanup_passes+1,cursor=NULL,error=NULL WHERE id=j.id;SET CONSTRAINTS ALL IMMEDIATE;RETURN true;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.finish_tenant_deletion(uuid,uuid) OWNER TO photo_fn_owner;

-- +goose Down
-- +goose StatementBegin
DO $$ BEGIN RAISE EXCEPTION 'Forward-only migration'; END $$;
-- +goose StatementEnd
